window.TADABBUR_KAHF = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة الكهف (١٨)، سورةٌ مكّيّةٌ فيها أربعُ قصصٍ عظيمة: أصحابُ الكهف، وصاحبا الجنّتين، وموسى والخضر، وذو القرنين؛ يُسنّ قراءتها يومَ الجمعة. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":18,"name":"الكهف","total_ayahs":110,"audio":[10,13,28,46,65,82,103,107,109,110],"passages":[{"title":"الحمدُ على إنزالِ الكتابِ القيّم","range":[1,3],"theme":"حمدُ الله على القرآنِ المستقيمِ الذي ينذر ويبشّر","verses":[{"n":1,"reflection":{"text":"«الحمد لله الذي أنزل على عبده الكتاب ولم يجعل له عوجا»: الحمدُ لله المستحقِّ للحمدِ كلِّه، الذي أنزل على عبده محمدٍ ﷺ القرآنَ، ولم يجعل فيه اعوجاجًا ولا اختلافًا ولا تناقضًا، بل هو مستقيمٌ حقّ؛ ففي هذا حمدُ الله على نعمةِ القرآنِ، وأنه لا عوجَ فيه، ووصفُ النبيِّ بالعبوديّةِ تشريفًا؛ فاحمد الله على نعمةِ القرآنِ المستقيم، وتمسّك به فلا عوجَ فيه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحمد لله"],"heart_state":{"text":"حمدُ الله على نعمةِ القرآنِ المستقيمِ الذي لا عوجَ فيه."},"action":{"text":"احمد الله على نعمةِ القرآنِ الذي أنزله لا عوجَ فيه ولا تناقض، وتمسّك به مستقيمًا، فهو الحقُّ من ربّك."}},{"n":2,"reflection":{"text":"«قيما لينذر بأسا شديدا من لدنه ويبشر المؤمنين الذين يعملون الصالحات أن لهم أجرا حسنا»: جعله قيّمًا مستقيمًا معتدلًا لا إفراطَ فيه ولا تفريط، لينذر الكافرين والعاصين عذابًا شديدًا من عند الله، ويبشّر المؤمنين العاملين الصالحاتِ بأنّ لهم أجرًا حسنًا (الجنّة)؛ ففي هذا أنّ القرآنَ بين إنذارٍ وبشارة، وأنّ البشرى للجامعين بين الإيمانِ والعمل؛ فاجمع بين الإيمانِ والعملِ لتنال البشرى، واحذر النذارةَ بالإعراض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين الإيمانِ والعملِ لنيلِ بشرى القرآن."},"action":{"text":"اجمع بين الإيمانِ والعملِ الصالح لتنال الأجرَ الحسنَ الذي بشّر به القرآن، واحذر النذارةَ بالكفرِ والإعراض."}},{"n":3,"reflection":{"text":"«ماكثين فيه أبدا»: ماكثين في ذلك الأجرِ الحسنِ (الجنّة) أبدًا لا يخرجون منه ولا ينقطع عنهم؛ ففي هذا أنّ نعيمَ الجنّةِ دائمٌ لا ينقطع؛ فاعمل للنعيمِ الباقي الدائمِ الذي لا زوالَ له، فذاك جزاءُ المؤمنين العاملين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنعيمِ الدائمِ الباقي الذي لا ينقطع."},"action":{"text":"اعمل بالإيمانِ والطاعةِ للأجرِ الحسنِ الدائمِ في الجنّة، فهو نعيمٌ لا ينقطع ولا يزول، جزاءً للمؤمنين الصالحين."}}]},{"title":"إنذارُ القائلين باتّخاذِ الولد","range":[4,5],"theme":"وعيدُ من نسب الولدَ إلى الله، وأنّ ذلك قولٌ عظيمٌ بلا علم","verses":[{"n":4,"reflection":{"text":"«وينذر الذين قالوا اتخذ الله ولدا»، ولينذر القرآنُ الذين قالوا اتّخذ الله ولدًا (من اليهودِ والنصارى والمشركين) عذابًا شديدًا؛ ففي هذا أنّ نسبةَ الولدِ إلى الله من أعظمِ ما يُنذَر عليه؛ فنزّه الله عن الولد، واحذر أن تنسب إليه ما لا يليق بجلاله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، والحذرُ من نسبةِ ما لا يليق به."},"action":{"text":"نزّه الله عن الولدِ والصاحبةِ وكلِّ نقص، واحذر نسبةَ ما لا يليق بجلاله، فذاك من أعظمِ ما يُنذَر عليه بالعذاب."}},{"n":5,"reflection":{"text":"«ما لهم به من علم ولا لآبائهم كبرت كلمة تخرج من أفواههم إن يقولون إلا كذبا»: ما لهؤلاء بنسبةِ الولدِ إلى الله من علمٍ ولا حجّة، ولا لآبائهم الذين قلّدوهم، عظُمت تلك الكلمةُ التي تخرج من أفواههم قبحًا وجرأة، ما يقولون إلا كذبًا محضًا؛ ففي هذا أنّ القولَ على الله بلا علمٍ كذبٌ عظيم، وأنّ التقليدَ لا يبرّر الباطل؛ فلا تقل على الله بلا علم، ولا تقلّد آباءك في باطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من القولِ على الله بلا علم، ونبذُ التقليدِ في الباطل."},"action":{"text":"لا تقل على الله بلا علمٍ ولا حجّة، ولا تقلّد آباءك أو غيرهم في باطل، فالقولُ على الله بلا علمٍ كذبٌ عظيمٌ يُنذَر عليه."}}]},{"title":"شفقةُ النبيِّ، وأنّ الدنيا دارُ ابتلاء","range":[6,8],"theme":"تسليةُ النبيِّ عن حزنه على إعراضهم، وأنّ زينةَ الأرضِ ابتلاءٌ زائل","verses":[{"n":6,"reflection":{"text":"«فلعلك باخع نفسك على آثارهم إن لم يؤمنوا بهذا الحديث أسفا»: فلعلّك يا محمد مهلكٌ نفسك حزنًا وأسفًا على إثرِ إعراضِ قومك إن لم يؤمنوا بهذا القرآن؛ ففي هذا بيانُ شدّةِ حرصِ النبيِّ ﷺ على هدايةِ قومه، وتسليةُ الله له بألّا يهلك نفسه حزنًا؛ فابذل الدعوةَ ولا تهلك نفسك حزنًا على من أعرض، فالهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ الدعوةِ بلا إهلاكِ النفسِ حزنًا على المعرضين."},"action":{"text":"ابذل الدعوةَ إلى الحقِّ بحرص، ولا تهلك نفسك حزنًا وأسفًا على من أعرض، فليس عليك إلا البلاغ، والهدايةُ بيدِ الله."}},{"n":7,"reflection":{"text":"«إنا جعلنا ما على الأرض زينة لها لنبلوهم أيهم أحسن عملا»: إنا جعلنا ما على الأرضِ من الأشجارِ والأنهارِ والمعادنِ وغيرها زينةً لها، لنختبر الناسَ أيّهم أحسنُ عملًا (أخلصُه لله وأصوبُه على السنّة)؛ ففي هذا أنّ زينةَ الدنيا ابتلاءٌ لا مقصودٌ لذاتها، وأنّ الغايةَ إحسانُ العملِ لا كثرتُه؛ فلا تغترّ بزينةِ الدنيا، واجعل همّك إحسانَ العملِ لله، فذاك مقصودُ الابتلاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أحسن عملا"],"heart_state":{"text":"عدمُ الاغترارِ بزينةِ الدنيا، وطلبُ إحسانِ العملِ لا كثرته."},"action":{"text":"لا تغترّ بزينةِ الدنيا فهي ابتلاء، واجعل همّك إحسانَ عملك بالإخلاصِ والمتابعةِ لا مجرّدَ كثرته، فذاك مقصودُ الله من خلقك."}},{"n":8,"reflection":{"text":"«وإنا لجاعلون ما عليها صعيدا جرزا»، وإنا لجاعلون ما على الأرضِ من الزينةِ بعد حينٍ ترابًا مستويًا يابسًا لا نباتَ فيه ولا شيء؛ ففي هذا أنّ زينةَ الدنيا إلى زوالٍ وفناء؛ فلا تتعلّق بزينةٍ زائلةٍ ستصير ترابًا، واعمل للباقي الذي لا يزول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ التعلّقِ بزينةِ الدنيا الزائلةِ التي تصير ترابًا."},"action":{"text":"لا تعلّق قلبك بزينةِ الدنيا، فكلُّ ما عليها إلى زوالٍ ويصير ترابًا يابسًا، فاعمل للباقي الذي لا يفنى."}}]},{"title":"مطلعُ قصّةِ أصحابِ الكهفِ ودعائهم","range":[9,12],"theme":"أنّ قصّةَ الفتيةِ آيةٌ، والتجاؤهم إلى الله بالدعاءِ ونومهم سنينَ ثم بعثهم","verses":[{"n":9,"reflection":{"text":"«أم حسبت أن أصحاب الكهف والرقيم كانوا من آياتنا عجبا»: أظننت يا محمد أنّ قصّةَ أصحابِ الكهفِ (الفتيةِ الذين ناموا في الكهفِ سنين) والرقيمِ (اللوحِ الذي كُتبت فيه أسماؤهم) كانت من آياتنا العجيبةَ الغريبة؟ بل ما في خلقِ السماواتِ والأرضِ من آياتنا أعجب؛ ففي هذا أنّ آياتِ الله في الكونِ أعظمُ من قصّةِ الكهف، وأنّ قدرةَ الله لا حدَّ لها؛ فتأمّل آياتِ الله الكثيرةَ في خلقه، فقصّةُ الكهفِ واحدةٌ من عجائبِ قدرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في آياتِ الله الكثيرةِ التي هي أعجبُ من قصّةِ الكهف."},"action":{"text":"تأمّل آياتِ الله في خلقِ الكونِ فهي أعظمُ عجبًا، واعلم أنّ قدرته لا حدَّ لها، وقصّةُ الكهفِ واحدةٌ من عجائبِ صنعه."}},{"n":10,"reflection":{"text":"«إذ أوى الفتية إلى الكهف فقالوا ربنا آتنا من لدنك رحمة وهيئ لنا من أمرنا رشدا»: اذكر إذ لجأ الفتيةُ المؤمنون إلى الكهفِ فرارًا بدينهم من قومهم الكفار، فقالوا داعين: ربّنا آتنا من عندك رحمةً تثبّتنا وتحفظنا، وهيّئ لنا من أمرنا رشدًا وطريقًا مستقيمًا نصيب به الحقّ؛ ففي هذا أنّ الفرارَ بالدينِ عند الفتنةِ سنّة، وأنّ الالتجاءَ إلى الله بالدعاءِ سبيلُ النجاة؛ فإذا خشيت على دينك ففرّ به إلى الله، وادعه أن يرحمك ويهيّئ لك الرشد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ربنا آتنا من لدنك رحمة"],"heart_state":{"text":"الفرارُ بالدينِ عند الفتنة، والالتجاءُ إلى الله بالدعاء."},"action":{"text":"إذا خشيت الفتنةَ على دينك ففرّ به إلى موضعٍ آمن، والجأ إلى الله بالدعاء أن يرحمك ويهيّئ لك الرشدَ والثبات، كما فعل الفتية."}},{"n":11,"reflection":{"text":"«فضربنا على آذانهم في الكهف سنين عددا»: فأنمناهم إنامةً ثقيلةً (ضربنا على آذانهم أي أنمناهم عن الأصوات) في الكهفِ سنينَ عديدةً (ثلاثمئةٍ وتسع سنين)؛ ففي هذا آيةٌ عظيمةٌ في حفظِ الله للفتيةِ بالنومِ الطويل، وأنّ من التجأ إليه حفظه؛ فاطمئن إلى أنّ الله يحفظ من التجأ إليه بأعجبِ الأسباب، فقد حفظ الفتيةَ بالنومِ سنينَ عددًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى حفظِ الله لمن التجأ إليه بأعجبِ الأسباب."},"action":{"text":"اطمئن إلى أنّ الله يحفظ من التجأ إليه ولاذ به، ولو بأسبابٍ عجيبة، فقد حفظ الفتيةَ في الكهفِ بالنومِ سنينَ طوالًا."}},{"n":12,"reflection":{"text":"«ثم بعثناهم لنعلم أي الحزبين أحصى لما لبثوا أمدا»: ثم أيقظناهم من نومهم الطويلِ لنُظهر (علمَ ظهورٍ) أيُّ الفريقين المتنازعين في مدّةِ لبثهم أضبطُ لحسابها؛ ففي هذا أنّ الله بعثهم آيةً، وأنّ اختلافَ الناسِ في المدّةِ من حكمةِ الابتلاء؛ فاطمئن إلى أنّ الله يبعث الموتى كما بعث النائمين، فالبعثُ حقٌّ يسيرٌ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ، فمن بعث النائمين قادرٌ على بعثِ الموتى."},"action":{"text":"أيقن بالبعثِ بعد الموت، فمن أيقظ الفتيةَ بعد نومٍ طويلٍ قادرٌ على بعثِ الموتى، فالبعثُ حقٌّ يسيرٌ على الله."}}]},{"title":"إيمانُ الفتيةِ وثباتُ قلوبهم","range":[13,14],"theme":"أنّ الله زاد الفتيةَ هدًى وربط على قلوبهم فأعلنوا التوحيد","verses":[{"n":13,"reflection":{"text":"«نحن نقص عليك نبأهم بالحق إنهم فتية آمنوا بربهم وزدناهم هدى»: نحن نقصّ عليك يا محمد خبرَ الفتيةِ بالصدق، إنهم شبابٌ آمنوا بربّهم إيمانًا صادقًا، فزدناهم هدًى وثباتًا وبصيرةً على إيمانهم؛ ففي هذا أنّ الإيمانَ سببُ المزيدِ من الهدى، وأنّ الشبابَ قد يكونون أهلَ الحقِّ والثبات؛ فآمن واعمل، فالله يزيد المؤمنين هدًى، ولا تحتقر الشبابَ في الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ الإيمانَ سببُ المزيدِ من الهدى، وأنّ الحقَّ لا يُحتقَر لسنّ."},"action":{"text":"حقّق إيمانك بالصدقِ والعمل، فالله يزيد المؤمنين هدًى، ولا تحتقر الحقَّ لصغرِ سنِّ حامله، فالفتيةُ كانوا أهلَ إيمانٍ وثبات."}},{"n":14,"reflection":{"text":"«وربطنا على قلوبهم إذ قاموا فقالوا ربنا رب السماوات والأرض لن ندعو من دونه إلها لقد قلنا إذا شططا»، وقوّينا قلوبهم بالصبرِ والثباتِ حين قاموا أمام الملكِ الكافرِ فأعلنوا: ربّنا هو ربُّ السماواتِ والأرض، لن نعبد من دونه إلهًا أبدًا، لقد قلنا إن دعونا غيره قولًا جائرًا بعيدًا عن الحقّ؛ ففي هذا أنّ الثباتَ على التوحيدِ من ربطِ الله على القلب، وأنّ إعلانَ الحقِّ عند الفتنةِ شجاعةُ إيمان؛ فاسأل الله أن يربط على قلبك بالثبات، وأعلن الحقَّ ولو أمام أهلِ الباطل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وربطنا على قلوبهم"],"heart_state":{"text":"طلبُ ربطِ القلبِ بالثبات، وإعلانُ الحقِّ عند الفتنة."},"action":{"text":"اسأل الله أن يربط على قلبك بالثباتِ على الحقّ، وأعلن التوحيدَ ولو أمام أهلِ الباطلِ والسلطان، كما ثبت الفتيةُ الفتية."}}]},{"title":"احتجاجُ الفتيةِ على قومهم، واعتزالُهم","range":[15,16],"theme":"إنكارُ الفتيةِ لشركِ قومهم، وعزمُهم على الفرارِ بدينهم","verses":[{"n":15,"reflection":{"text":"«هؤلاء قومنا اتخذوا من دونه آلهة لولا يأتون عليهم بسلطان بين فمن أظلم ممن افترى على الله كذبا»: قال الفتيةُ منكرين: هؤلاءِ قومُنا اتّخذوا من دون الله آلهةً يعبدونها، هلّا يأتون على عبادتها بحجّةٍ واضحة؟ ولا حجّةَ لهم؛ فلا أحدَ أظلمُ ممّن اختلق على الله كذبًا بجعلِ الشركاءِ له؛ ففي هذا أنّ العبادةَ لا تصحّ إلا بدليل، وأنّ الشركَ افتراءٌ لا برهانَ عليه؛ فلا تعبد إلا بدليلٍ من الله، فعبادةُ ما لا دليلَ عليه افتراءٌ وظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ العبادةَ لا تصحّ إلا بدليل، وأنّ الشركَ افتراءٌ بلا برهان."},"action":{"text":"لا تعبد إلا الله بدليلٍ من الوحي، فعبادةُ ما لا برهانَ عليه افتراءٌ على الله وأعظمُ الظلم، فاطلب الدليلَ على كلِّ ما تعبد."}},{"n":16,"reflection":{"text":"«وإذ اعتزلتموهم وما يعبدون إلا الله فأووا إلى الكهف ينشر لكم ربكم من رحمته ويهيئ لكم من أمركم مرفقا»: قال بعضهم لبعض: وإذ فارقتم قومكم وما يعبدون من دون الله، وبقيتم على عبادةِ الله وحده، فالجؤوا إلى الكهفِ فرارًا بدينكم، ينشر لكم ربّكم من رحمته ويحفظكم، ويهيّئ لكم من أمركم ما ترتفقون به وتنتفعون؛ ففي هذا أنّ الفرارَ بالدينِ يعقبه فرجٌ ورحمةٌ من الله؛ فإذا فارقت أهلَ الباطلِ لله ففرّ إلى الله، وثق بأنه ينشر عليك رحمته وييسّر أمرك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الفرارُ بالدينِ إلى الله، والثقةُ بأنه ينشر الرحمةَ وييسّر الأمر."},"action":{"text":"إذا اعتزلت أهلَ الباطلِ وفارقتهم لله ففرّ إلى الله والزم الحقّ، وثق بأنه ينشر عليك رحمته وييسّر لك أمرك ومرفقك."}}]},{"title":"حفظُ الله للفتيةِ في كهفهم","range":[17,18],"theme":"آيةُ إمالةِ الشمسِ عن الكهف، ورعايةُ الله لهم في نومهم","verses":[{"n":17,"reflection":{"text":"«وترى الشمس إذا طلعت تزاور عن كهفهم ذات اليمين وإذا غربت تقرضهم ذات الشمال وهم في فجوة منه ذلك من آيات الله من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا»، وترى الشمسَ إذا طلعت تميل عن كهفهم جهةَ اليمينِ فلا تصيبهم، وإذا غربت تتركهم وتتجاوزهم جهةَ الشمال، وهم في متّسعٍ من الكهفِ يصيبهم الهواءُ ولا يؤذيهم الحرّ (فحفظهم الله من الشمسِ وأبقى أجسادهم)؛ ذلك من آياتِ الله وحفظه؛ من يهده الله فهو المهتدي، ومن يخذله فلن تجد له وليًّا يرشده؛ ففي هذا لطفُ الله بأوليائه في أدقِّ أحوالهم، وأنّ الهدايةَ بيده؛ فاطمئن إلى أنّ الله يرعى أولياءه في أدقِّ شؤونهم، واسأله الهداية.","source":"تفسير السعدي","grade":"ma'thur"},"names":["من يهد الله فهو المهتد"],"heart_state":{"text":"الاطمئنانُ إلى رعايةِ الله لأوليائه، وطلبُ الهدايةِ منه."},"action":{"text":"اطمئن إلى أنّ الله يرعى أولياءه في أدقِّ أحوالهم كما رعى الفتيةَ من الشمس، واسأله الهدايةَ فمن يهده فهو المهتدي."}},{"n":18,"reflection":{"text":"«وتحسبهم أيقاظا وهم رقود ونقلبهم ذات اليمين وذات الشمال وكلبهم باسط ذراعيه بالوصيد لو اطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا»، وتظنّهم أيقاظًا لأنّ أعينهم مفتوحة، وهم نيامٌ في الحقيقة، ونقلّبهم يمينًا وشمالًا لئلا تأكل الأرضُ أجسادهم، وكلبهم باسطٌ ذراعيه عند بابِ الكهفِ يحرسهم؛ لو رأيتهم لولّيت هاربًا منهم وامتلأت رعبًا لِما ألبسهم الله من الهيبة؛ ففي هذا كمالُ حفظِ الله لهم وإلباسِهم الهيبة؛ فاطمئن إلى أنّ الله يحفظ أولياءه ويلبسهم هيبةً تحميهم، فمن حفظه الله فلا يصل إليه سوء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاطمئنانُ إلى حفظِ الله لأوليائه وإلباسِهم الهيبةَ الحامية."},"action":{"text":"اطمئن إلى أنّ الله يحفظ أولياءه بأتمِّ حفظ ويلبسهم هيبةً تحميهم، فمن حفظه الله لم يصل إليه أذى، فالتجئ إليه واعتصم به."}}]},{"title":"بعثُ الفتيةِ وتساؤلُهم، ولطفُهم في السرّ","range":[19,20],"theme":"إيقاظُ الفتيةِ وحيرتُهم في المدّة، وحرصُهم على السرّيّةِ خوفَ الفتنة","verses":[{"n":19,"reflection":{"text":"«وكذلك بعثناهم ليتساءلوا بينهم قال قائل منهم كم لبثتم قالوا لبثنا يوما أو بعض يوم قالوا ربكم أعلم بما لبثتم فابعثوا أحدكم بورقكم هذه إلى المدينة فلينظر أيها أزكى طعاما فليأتكم برزق منه وليتلطف ولا يشعرن بكم أحدا»، وكذلك أيقظناهم من نومهم ليسأل بعضهم بعضًا، فقال قائل: كم لبثتم؟ قالوا: يومًا أو بعضَ يوم (لظنّهم قصرَ المدّة)، ثم فوّضوا العلمَ لله: ربّكم أعلم بما لبثتم؛ فابعثوا أحدكم بنقودكم هذه إلى المدينةِ فلينظر أطيبَ طعامٍ وأحلَّه فليأتكم برزقٍ منه، وليترفّق في تصرّفه ولا يُشعِرنّ بكم أحدًا؛ ففي هذا تفويضُهم العلمَ لله، وحرصُهم على الطيّبِ من الطعام، والتلطّفُ في الأمور؛ فتحرَّ الطيّبَ من الرزق، وتلطّف في تصرّفاتك، وفوّض ما جهلته إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وليتلطف"],"heart_state":{"text":"تحرّي الطيّبِ من الرزق، والتلطّفُ في الأمور، وتفويضُ العلمِ لله."},"action":{"text":"تحرَّ الطيّبَ الحلالَ من رزقك، وتلطّف في تصرّفاتك وتعامَل بحكمة، وفوّض ما تجهله إلى الله، كما فعل فتيةُ الكهف."}},{"n":20,"reflection":{"text":"«إنهم إن يظهروا عليكم يرجموكم أو يعيدوكم في ملتهم ولن تفلحوا إذا أبدا»: قال الفتيةُ محذّرين رسولهم: إنّ قومنا إن يطّلعوا عليكم يقتلوكم بالرجمِ أو يردّوكم إلى دينهم الكفرِ بالقوّة، ولن تفلحوا حينئذٍ أبدًا في الدنيا ولا الآخرة إن رجعتم عن دينكم؛ ففي هذا حرصُ الفتيةِ على دينهم وخوفهم من الفتنة، وأنّ الردّةَ عن الحقِّ خسرانٌ أبديّ؛ فاحرص على دينك كحرصِ الفتية، واحذر أسبابَ الفتنةِ عنه، فالردّةُ عنه لا فلاحَ بعدها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على الدينِ والحذرُ من أسبابِ الفتنةِ عنه."},"action":{"text":"احرص على دينك أشدَّ الحرص كما حرص الفتية، واحذر مواطنَ الفتنةِ التي قد تردّك عن الحقّ، فالردّةُ عن الدينِ خسرانٌ لا فلاحَ بعده."}}]},{"title":"الاطّلاعُ عليهم دليلًا على البعث","range":[21,21],"theme":"أنّ الله أظهر أمرَهم ليُعلَم أنّ وعدَه حقٌّ وأنّ الساعةَ آتية","verses":[{"n":21,"reflection":{"text":"«وكذلك أعثرنا عليهم ليعلموا أن وعد الله حق وأن الساعة لا ريب فيها إذ يتنازعون بينهم أمرهم فقالوا ابنوا عليهم بنيانا ربهم أعلم بهم قال الذين غلبوا على أمرهم لنتخذن عليهم مسجدا»، وكذلك أطلعنا أهلَ المدينةِ على الفتية (حين خرج مبعوثهم بنقودٍ قديمة)، ليعلموا أنّ وعدَ الله بالبعثِ حقّ، وأنّ الساعةَ لا شكَّ فيها (فقصّةُ الفتيةِ آيةٌ على البعث)؛ إذ يتنازع الناسُ في شأنهم بعد موتهم، فقال فريق: ابنوا عليهم بنيانًا يسترهم، ربّهم أعلم بحالهم، وقال الغالبون على الأمر: لنتّخذنّ على كهفهم مسجدًا؛ ففي هذا أنّ قصّةَ الكهفِ برهانٌ على البعث؛ فاستدلّ بقصّةِ الفتيةِ على أنّ البعثَ حقٌّ والساعةَ آتية، فمن أنامهم وأيقظهم يبعث الموتى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ بقصّةِ الكهفِ على حقّيّةِ البعثِ وقربِ الساعة."},"action":{"text":"استدلّ بقصّةِ أصحابِ الكهفِ على أنّ وعدَ الله بالبعثِ حقٌّ وأنّ الساعةَ آتية، فمن أنامهم سنينَ ثم أيقظهم قادرٌ على بعثِ الموتى."}}]},{"title":"النهيُ عن الخوضِ في المغيّبات","range":[22,22],"theme":"أنّ عددَ الفتيةِ من الغيب، والنهيُ عن المراءِ فيه وطلبِ علمه من أهلِ الكتاب","verses":[{"n":22,"reflection":{"text":"«سيقولون ثلاثة رابعهم كلبهم ويقولون خمسة سادسهم كلبهم رجما بالغيب ويقولون سبعة وثامنهم كلبهم قل ربي أعلم بعدتهم ما يعلمهم إلا قليل فلا تمار فيهم إلا مراء ظاهرا ولا تستفت فيهم منهم أحدا»: سيقول المتنازعون في عددِ الفتية: هم ثلاثةٌ رابعهم كلبهم، ويقول آخرون: خمسةٌ سادسهم كلبهم، قولًا بلا علمٍ رجمًا بالغيب، ويقول آخرون: سبعةٌ وثامنهم كلبهم؛ قل يا محمد: ربّي أعلم بعددهم، ما يعلمهم إلا قليلٌ من الناس؛ فلا تجادل في شأنهم إلا جدالًا ظاهرًا يسيرًا (بما أُوحي إليك)، ولا تسأل عنهم أحدًا من أهلِ الكتابِ فليسوا على علمٍ يقين؛ ففي هذا النهيُ عن الخوضِ في المغيّباتِ التي لا فائدةَ فيها، وأدبُ الاكتفاءِ بما جاء في الوحي؛ فلا تخض فيما لا علمَ لك به ولا فائدةَ فيه، واكتفِ بما جاء في الوحي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بالوحي، وتركُ الخوضِ في المغيّباتِ التي لا فائدةَ فيها."},"action":{"text":"لا تخض فيما لا علمَ لك به من المغيّبات، ولا تجادل فيما لا فائدةَ فيه، واكتفِ بما جاء في الوحي، ولا تلتمس العلمَ من غيرِ أهله."}}]},{"title":"أدبُ الاستثناءِ وردُّ العلمِ إلى الله","range":[23,26],"theme":"النهيُ عن الجزمِ بالمستقبلِ دون مشيئةِ الله، وأنّ الغيبَ لله وحده","verses":[{"n":23,"reflection":{"text":"«ولا تقولن لشيء إني فاعل ذلك غدا»: لا تقولنّ يا محمد لأمرٍ تعزم عليه: إني فاعلٌ ذلك غدًا، جازمًا به دون أن تعلّقه بمشيئةِ الله؛ ففي هذا أدبٌ عظيمٌ مع الله، أنّ العبدَ لا يملك من أمره شيئًا إلا بمشيئةِ ربّه؛ فلا تجزم بمستقبلٍ لا تملكه، واعلم أنّ الأمورَ كلَّها بيدِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"افتقارُ العبدِ إلى مشيئةِ الله في كلِّ أمر."},"action":{"text":"لا تجزم بفعلِ شيءٍ في المستقبلِ إلا معلّقًا بمشيئةِ الله، فأمرُك كلُّه بيدِ ربّك لا بيدك، واستشعر افتقارَك إليه في كلِّ عزم."}},{"n":24,"reflection":{"text":"«إلا أن يشاء الله واذكر ربك إذا نسيت وقل عسى أن يهدين ربي لأقرب من هذا رشدا»: إلا أن تقول: إن شاء الله؛ واذكر ربّك بالاستثناءِ إذا نسيته، أو اذكره متى غفلت، وقل: عسى أن يهديني ربّي لِما هو أقربُ من هذا خيرًا ورشدًا؛ ففي هذا تعليمُ الأدبِ في تعليقِ الأمورِ بالمشيئة، وتداركِ النسيانِ بالذكر، والرجاءِ في هدايةِ الله؛ فقل «إن شاء الله»، وإذا نسيتها فاستدركها، وارجُ من ربّك خيرَ الهدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["واذكر ربك إذا نسيت"],"heart_state":{"text":"تعليقُ الأمرِ بالمشيئة، وتداركُ النسيانِ بالذكر، والرجاء."},"action":{"text":"قل «إن شاء الله» عند كلِّ عزم، وإذا نسيتها فاستدركها متى ذكرت، وارجُ من ربّك أن يهديك لأقربَ من مرادك رشدًا وخيرًا."}},{"n":25,"reflection":{"text":"«ولبثوا في كهفهم ثلاث مائة سنين وازدادوا تسعا»، ومكث الفتيةُ في كهفهم ثلاثمئةِ سنةٍ وتسعَ سنين نيامًا بحفظِ الله، أخبر الله بمدّةِ لبثهم بعد أن اختلف الناسُ فيها؛ ففي هذا أنّ الله يحفظ أولياءه دهورًا، وأنّ الخبرَ اليقينَ في مدّتهم من الله لا من ظنونِ الناس؛ فثق بقدرةِ الله على الحفظِ مهما طالت المدّة، وردَّ العلمَ إلى خبره الصادق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بقدرةِ الله على الحفظِ الطويل، وردُّ اليقينِ إلى خبره."},"action":{"text":"ثق بأنّ الله يحفظ أولياءه ولو مئاتِ السنين كما حفظ الفتية، وردَّ العلمَ في المُغيَّباتِ إلى خبرِ الله الصادقِ لا إلى ظنونِ الناس."}},{"n":26,"reflection":{"text":"«قل الله أعلم بما لبثوا له غيب السماوات والأرض أبصر به وأسمع ما لهم من دونه من ولي ولا يشرك في حكمه أحدا»: قل يا محمد: الله أعلمُ بمدّةِ لبثهم، له وحده علمُ غيبِ السماواتِ والأرض، ما أبصرَه بكلِّ شيءٍ وأسمعَه لكلِّ شيء! ما للخلقِ من دونه من وليٍّ يتولاهم، ولا يشرك في حكمه وقضائه أحدًا؛ ففي هذا انفرادُ الله بعلمِ الغيبِ وكمالِ سمعه وبصره وتفرّدِه بالولايةِ والحكم؛ فردَّ علمَ الغيبِ إليه وحده، وأخلص له الولايةَ والتحاكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["له غيب السماوات والأرض","أبصر به وأسمع"],"heart_state":{"text":"انفرادُ الله بعلمِ الغيبِ والولايةِ والحكم."},"action":{"text":"ردَّ علمَ ما غاب إلى الله وحده، وأخلص له الولايةَ فلا وليَّ سواه، واحتكم إلى حكمه فلا شريكَ له في قضائه وأمره."}}]},{"title":"الأمرُ بتلاوةِ الوحيِ والصبرِ مع أهلِ الذكر","range":[27,28],"theme":"اتّباعُ كلماتِ الله التي لا تُبدَّل، ومجالسةُ الفقراءِ الذاكرين","verses":[{"n":27,"reflection":{"text":"«واتل ما أوحي إليك من كتاب ربك لا مبدل لكلماته ولن تجد من دونه ملتحدا»، واتلُ يا محمد ما أوحاه إليك ربّك من كتابه واعمل به، لا أحدَ يبدّل كلماتِه لصدقها وعدلها، ولن تجد من دونه ملجأً تلجأ إليه؛ ففي هذا الأمرُ بلزومِ الوحيِ تلاوةً وعملًا، وأنّ كلامَ الله محفوظٌ لا يُبدَّل، وأنّ الملجأَ إليه وحده؛ فالزم كتابَ ربّك تاليًا عاملًا، واجعل ملجأك إليه لا إلى سواه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الوحيِ تلاوةً وعملًا، وأنّ الملجأَ إلى الله وحده."},"action":{"text":"الزم كتابَ ربّك تلاوةً وتدبّرًا وعملًا، فكلماتُه لا تُبدَّل، ولا ملجأَ لك من دونه؛ فاجعل التجاءك إلى الله وحده في كلِّ شأن."}},{"n":28,"reflection":{"text":"«واصبر نفسك مع الذين يدعون ربهم بالغداة والعشي يريدون وجهه ولا تعد عيناك عنهم تريد زينة الحياة الدنيا ولا تطع من أغفلنا قلبه عن ذكرنا واتبع هواه وكان أمره فرطا»، واحبس نفسك مع الفقراءِ الذين يدعون ربّهم أوّلَ النهارِ وآخرَه يريدون وجهه لا الدنيا، ولا تتجاوزهم عيناك إلى زينةِ الدنيا وأهلها، ولا تطع من أغفلنا قلبه عن ذكرنا واتّبع هواه وكان أمره ضياعًا؛ ففي هذا فضلُ مجالسةِ الذاكرين المخلصين، والنهيُ عن إيثارِ أهلِ الدنيا عليهم؛ فالزم صحبةَ أهلِ الذكرِ والإخلاص، ولا تُؤثر عليهم أهلَ الغفلةِ والهوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ صحبةِ الذاكرين المخلصين، وعدمُ إيثارِ أهلِ الدنيا."},"action":{"text":"الزم مجالسةَ الفقراءِ الذاكرين المخلصين لله، ولا تصرف قلبك عنهم رغبةً في زينةِ الدنيا، ولا تطع الغافلَ المتّبعَ لهواه."},"sabab":{"text":"نزلت حين اقترح أشرافُ قريشٍ على النبيِّ ﷺ أن يُبعِد الفقراءَ من أصحابه ليجالسوه، فنهاه الله أن يطردهم وأمره بالصبرِ معهم.","source":"تفسير ابن كثير (بنحوه)","grade":"ma'thur"}}]},{"title":"الحقُّ من الله، ومصيرُ الفريقين","range":[29,31],"theme":"حريةُ الاختيارِ مع تبعتها: نارٌ للظالمين وجناتٌ للمحسنين","verses":[{"n":29,"reflection":{"text":"«وقل الحق من ربكم فمن شاء فليؤمن ومن شاء فليكفر إنا أعتدنا للظالمين نارا أحاط بهم سرادقها وإن يستغيثوا يغاثوا بماء كالمهل يشوي الوجوه بئس الشراب وساءت مرتفقا»، وقل يا محمد: هذا الحقُّ من ربّكم، فمن شاء فليؤمن ومن شاء فليكفر (تهديدٌ لا تخيير)، إنا أعتدنا للظالمين نارًا أحاط بهم سورُها، وإن استغاثوا من العطشِ أُغيثوا بماءٍ كعكرِ الزيتِ المغليّ يشوي وجوههم، بئس ذلك الشرابُ وساءت النارُ منزلًا؛ ففي هذا أنّ الحقَّ بيّنٌ وأنّ العبدَ محاسبٌ على اختياره، وهولُ عذابِ الظالمين؛ فاختر الإيمانَ بعد وضوحِ الحقّ، واحذر عاقبةَ الظلمِ والكفر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"وضوحُ الحقِّ ومسؤوليةُ الاختيار، والخوفُ من عذابِ الظالمين."},"action":{"text":"اختر الإيمانَ وقد تبيّن لك الحقُّ من ربّك، واحذر أن تكون من الظالمين الذين أُعِدَّت لهم النار؛ فالاختيارُ حرّ لكنّ تبعتَه عظيمة."}},{"n":30,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات إنا لا نضيع أجر من أحسن عملا»: إنّ الذين جمعوا بين الإيمانِ والعملِ الصالح، إنا لا نضيع أجرَ من أحسن عمله، بل نحفظه ونوفّيه أكملَ الجزاء؛ ففي هذا أنّ الإحسانَ في العملِ لا يضيع عند الله، وأنّ الجزاءَ مقرونٌ بالإيمانِ والعمل؛ فأحسن عملك وأتقنه لله، وثق بأنّ الله لا يضيع أجرَ محسن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى أنّ الله لا يضيع أجرَ المحسنين."},"action":{"text":"اجمع بين الإيمانِ والعملِ الصالح، وأحسن عملك وأتقنه لله، وثق بأنّ الله يحفظ أجرك ولا يضيع عمل محسنٍ أبدًا."}},{"n":31,"reflection":{"text":"«أولئك لهم جنات عدن تجري من تحتهم الأنهار يحلون فيها من أساور من ذهب ويلبسون ثيابا خضرا من سندس وإستبرق متكئين فيها على الأرائك نعم الثواب وحسنت مرتفقا»: أولئك المؤمنون العاملون لهم جناتُ إقامةٍ دائمةٍ تجري من تحتهم الأنهار، يُزيَّنون فيها بأساورِ الذهب، ويلبسون ثيابًا خضرًا من رقيقِ الحريرِ وغليظه، متّكئين على الأسرّةِ المزيّنة؛ نعم الثوابُ ثوابهم وحسنت الجنةُ منزلًا؛ ففي هذا وصفُ نعيمِ أهلِ الجنةِ مقابلَ عذابِ الظالمين؛ فاعمل لهذا النعيمِ المقيم، وقابِل بين المصيرين لتؤثر الباقيةَ على الفانية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرغبةُ في نعيمِ الجنةِ الباقي، والموازنةُ بين المصيرين."},"action":{"text":"اعمل لجناتِ عدنٍ ونعيمها المقيم، وقابِل بين ثوابِ المحسنين وعذابِ الظالمين لتؤثر الآخرةَ الباقيةَ على الدنيا الفانية."}}]},{"title":"مثلُ صاحبِ الجنّتين: غرورُ الغنى","range":[32,36],"theme":"رجلٌ آتاه الله جنّتين فبطر وكفر بربّه وأنكر البعث","verses":[{"n":32,"reflection":{"text":"«واضرب لهم مثلا رجلين جعلنا لأحدهما جنتين من أعناب وحففناهما بنخل وجعلنا بينهما زرعا»، واضرب يا محمد للناسِ مثلًا برجلين: جعلنا لأحدهما بستانين من أعنابٍ أحطناهما بالنخل، وجعلنا بينهما زرعًا، فاجتمع له كلُّ ما يشتهي؛ ففي هذا تصويرُ نعمةِ الدنيا التي تفتن صاحبَها، تمهيدًا لعاقبةِ من اغترّ بها؛ فتأمّل نعمَ الله وانظر إلى ما تؤول إليه، ولا تغترَّ بزهرةِ الدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمِ الدنيا وعدمُ الاغترارِ بها."},"action":{"text":"تأمّل نعمَ الله عليك وانظر إلى عاقبتها، فالدنيا مثلٌ يُضرب لا دارُ قرار؛ فلا تغترَّ بزهرتها ولا تنسَ المُنعِم."}},{"n":33,"reflection":{"text":"«كلتا الجنتين آتت أكلها ولم تظلم منه شيئا وفجرنا خلالهما نهرا»: كِلا البستانين أعطى ثمره كاملًا لم ينقص منه شيئًا، وشقَقنا بينهما نهرًا يسقيهما دائمًا؛ ففي هذا تمامُ النعمةِ وكمالُها على صاحبها، وهو ابتلاءٌ ليُشكَر لا ليُبطَر؛ فإذا تمّت عليك النعمةُ فاشكر المُنعِم، واعلم أنّ تمامها ابتلاءٌ لك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ تمامِ النعمة، والعلمُ بأنها ابتلاء."},"action":{"text":"إذا أُتِمَّت عليك النعمةُ فقابلها بالشكرِ لا بالبطر، واعلم أنّ سعةَ الرزقِ ابتلاءٌ يكشف حقيقةَ العبدِ لا مجردَ عطاء."}},{"n":34,"reflection":{"text":"«وكان له ثمر فقال لصاحبه وهو يحاوره أنا أكثر منك مالا وأعز نفرا»، وكان لصاحبِ الجنّتين أنواعُ الأموالِ والثمار، فقال لصاحبه المؤمنِ وهو يجادله مفتخرًا: أنا أكثرُ منك مالًا وأعزُّ أنصارًا وعشيرة؛ ففي هذا أنّ المالَ يُبطِر صاحبَه فيفخر على غيره ويحتقره؛ فاحذر أن يستدرجك مالك إلى الكِبرِ والفخرِ على الناس، فالفخرُ بالمالِ مرضُ القلب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يورث المالُ الكِبرَ والفخر."},"action":{"text":"احذر أن يجرّك مالك أو جاهك إلى الفخرِ على الناسِ واحتقارهم، فالتفاخرُ بالدنيا أوّلُ درجاتِ الطغيان، وإنما الغنى غنى القلب."}},{"n":35,"reflection":{"text":"«ودخل جنته وهو ظالم لنفسه قال ما أظن أن تبيد هذه أبدا»، ودخل بستانه معجَبًا وهو ظالمٌ لنفسه بكفره وكِبره، فقال مغترًّا: ما أظنّ أن تفنى هذه الجنةُ أبدًا؛ ففي هذا أنّ الاغترارَ بالدنيا يُنسي زوالها ويورث الظلمَ والغفلة؛ فلا تظنَّ نعمةً باقيةً، واستحضر أنّ كلَّ ما في الدنيا إلى فناء، فلا يغرّنك دوامُها الظاهر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ زوالِ الدنيا، والحذرُ من الاغترارِ بدوامها."},"action":{"text":"لا تظنَّ نعمةَ الدنيا باقيةً لك أبدًا، فكلُّ ما فيها إلى زوال؛ فاستحضر فناءها لئلا تظلم نفسك بالغفلةِ والغرور."}},{"n":36,"reflection":{"text":"«وما أظن الساعة قائمة ولئن رددت إلى ربي لأجدن خيرا منها منقلبا»، وما أظنّ القيامةَ واقعةً، ولئن رُددتُ إلى ربّي على زعمكم لأجدنّ عنده خيرًا من هذه الجنةِ مرجعًا؛ ففي هذا اجتماعُ إنكارِ البعثِ مع الغرورِ على الله وتمنّي الخيرِ عنده بلا إيمان؛ فاحذر أن يخدعك المالُ فتنكر الآخرةَ أو تتمنّى على الله الأمانيَّ بلا عمل، فالكفرُ لا يورث كرامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من إنكارِ البعثِ ومن الأمانيِّ الكاذبةِ على الله."},"action":{"text":"احذر أن يجرّك الغنى إلى الغفلةِ عن الآخرةِ أو التمنّي على الله بلا عمل؛ فالنعمةُ في الدنيا ليست دليلَ رضا، ولا تُغني عن الإيمان."}}]},{"title":"جوابُ المؤمنِ: التوحيدُ والاستثناء","range":[37,41],"theme":"موعظةُ الصاحبِ المؤمن، ودعوتُه إلى الإقرارِ بالله وقولِ «ما شاء الله»","verses":[{"n":37,"reflection":{"text":"«قال له صاحبه وهو يحاوره أكفرت بالذي خلقك من تراب ثم من نطفة ثم سواك رجلا»: قال له صاحبه المؤمنُ محاورًا: أكفرتَ بالذي خلق أصلك من تراب، ثم خلقك من نطفة، ثم سوّاك رجلًا كاملًا؟ ففي هذا الاحتجاجُ على المنكِرِ بخلقِ الله له بعد العدم، فالقادرُ على البدءِ قادرٌ على الإعادة؛ فتذكّر أصلَ خلقك من ترابٍ ونطفة لينكسر كِبرُك، ويثبت لك البعث.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ أصلِ الخلقِ لكسرِ الكِبرِ وإثباتِ البعث."},"action":{"text":"تذكّر أنّ الله خلقك من ترابٍ ثم نطفةٍ ثم سوّاك، فمن أوجدك من العدمِ قادرٌ على بعثك؛ فليكسر ذلك كِبرك ويثبّت إيمانك بالمعاد."}},{"n":38,"reflection":{"text":"«لكنا هو الله ربي ولا أشرك بربي أحدا»: قال المؤمن: لكنْ أنا أقول: هو الله ربّي، لا أشرك به أحدًا في عبادتي؛ ففي هذا إعلانُ التوحيدِ الخالصِ في وجهِ الكافرِ المغتر؛ فأعلن أنت توحيدَك ولا تستحِ من الحقّ أمام أهلِ الدنيا، فكلمةُ التوحيدِ أعزُّ من كلِّ مالٍ ونفر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعلانُ التوحيدِ الخالصِ والاعتزازُ به."},"action":{"text":"أعلن توحيدك لله بلا مواراة: «هو الله ربّي ولا أشرك بربّي أحدًا»، ولا يهزّك مالُ أهلِ الدنيا أو جاههم عن الاعتزازِ بدينك."}},{"n":39,"reflection":{"text":"«ولولا إذ دخلت جنتك قلت ما شاء الله لا قوة إلا بالله إن ترن أنا أقل منك مالا وولدا»: هلّا حين دخلت جنتك قلت: ما شاء الله كان، لا قوةَ لي على شيءٍ إلا بالله؛ إن رأيتني أقلَّ منك مالًا وولدًا؛ ففي هذا تعليمُ ردِّ النعمةِ إلى المُنعِم وقولِ «ما شاء الله لا قوة إلا بالله» عند رؤيةِ ما يعجب؛ فقلها عند كلِّ نعمةٍ تراها لك أو لغيرك، فبها يُحفَظ العبدُ من العينِ والبطر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ما شاء الله لا قوة إلا بالله"],"heart_state":{"text":"ردُّ النعمةِ إلى الله بقولِ «ما شاء الله لا قوة إلا بالله»."},"action":{"text":"قل عند كلِّ ما يعجبك من مالٍ أو ولدٍ أو نعمة: «ما شاء الله لا قوة إلا بالله»، فبها تردّ النعمةَ لأهلها وتُحفَظ من الطغيانِ والعين."}},{"n":40,"reflection":{"text":"«فعسى ربي أن يؤتين خيرا من جنتك ويرسل عليها حسبانا من السماء فتصبح صعيدا زلقا»: فعسى ربّي أن يعطيني خيرًا من جنتك، ويرسل على جنتك عذابًا من السماء فتصبح أرضًا ملساءَ زَلِقةً لا نباتَ فيها؛ ففي هذا رجاءُ المؤمنِ فضلَ ربّه، وتحذيرُه الكافرَ من زوالِ نعمته بعقوبةٍ مفاجئة؛ فعلّق رجاءك بفضلِ الله لا بما في يدك، واحذر أن تُنزَع النعمةُ بذنبٍ في لحظة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعليقُ الرجاءِ بفضلِ الله، والحذرُ من زوالِ النعمة."},"action":{"text":"علّق رجاءك بفضلِ الله لا بما تملك، واعلم أنّ النعمةَ قد تُنزَع في لحظةٍ بذنب؛ فاشكرها واحفظها بطاعةِ من أعطاها."}},{"n":41,"reflection":{"text":"«أو يصبح ماؤها غورا فلن تستطيع له طلبا»: أو يصبح ماءُ جنتك غائرًا في الأرضِ فلن تقدر على ردِّه ولا الوصولِ إليه؛ ففي هذا أنّ أسبابَ النعمةِ بيدِ الله يمنعها متى شاء فلا حيلةَ للعبد؛ فاعلم أنّ ماءك ورزقك بيدِ الله، فإن أمسكه لم يقدر أحدٌ على ردّه، فالجأ إليه واشكره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بأنّ أسبابَ الرزقِ بيدِ الله وحده."},"action":{"text":"اعلم أنّ ماءك ورزقك وأسبابَ نعمتك بيدِ الله، إن أمسكها لم يردَّها أحد؛ فلا تركن إلى الأسباب، والجأ إلى مسبِّبها واشكره."}}]},{"title":"عاقبةُ المغترّ: الندمُ حين لا ينفع","range":[42,44],"theme":"هلاكُ الجنّتين، وندمُ صاحبها، وأنّ الولايةَ لله الحقّ","verses":[{"n":42,"reflection":{"text":"«وأحيط بثمره فأصبح يقلب كفيه على ما أنفق فيها وهي خاوية على عروشها ويقول يا ليتني لم أشرك بربي أحدا»، وأُهلِك ثمرُ جنّتيه جميعًا، فأصبح يقلّب كفّيه ندمًا وحسرةً على ما أنفق فيها، وهي ساقطةٌ خاويةٌ على دعائمها، ويقول: يا ليتني لم أشرك بربّي أحدًا؛ ففي هذا أنّ النعمةَ تزول فجأةً فلا يبقى إلا الحسرة، وأنّ الندمَ حينئذٍ لا ينفع؛ فبادر بالتوحيدِ والشكرِ قبل أن يفوت، فالندمُ بعد الهلاكِ لا يردّ شيئًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بزوالِ النعمة، والمبادرةُ بالتوبةِ قبل الفوات."},"action":{"text":"بادر بالتوحيدِ والشكرِ والتوبةِ قبل أن تزول نعمتك، فالندمُ بعد فواتِ الأمرِ حسرةٌ لا تردّ شيئًا؛ فلا تؤخّر رجوعك إلى الله."}},{"n":43,"reflection":{"text":"«ولم تكن له فئة ينصرونه من دون الله وما كان منتصرا»، ولم يكن لهذا المغترِّ جماعةٌ يمنعونه من عذابِ الله كما كان يفخر بنفَره، ولا كان قادرًا على نصرِ نفسه؛ ففي هذا أنّ ما يتّكئ عليه المغرورُ من مالٍ وأنصارٍ لا يغني عنه من الله شيئًا؛ فلا تركن إلى مالٍ ولا جاهٍ ولا نفر، فلن ينصرك من الله إلا الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الركونِ إلى الأسبابِ دون الله في دفعِ قدره."},"action":{"text":"لا تتّكئ على مالٍ أو أنصارٍ أو منصبٍ في دفعِ ما قدّره الله، فلا ناصرَ من دونه؛ فاجعل اعتمادك على الله وحده لا على أسبابك."}},{"n":44,"reflection":{"text":"«هنالك الولاية لله الحق هو خير ثوابا وخير عقبا»: في ذلك الموطنِ العصيبِ تكون الولايةُ والنصرةُ لله وحده الحقّ، هو خيرٌ ثوابًا لأوليائه وخيرٌ عاقبةً لمن اتّقاه؛ ففي هذا أنّ العزَّ والنصرَ والعاقبةَ الحسنةَ كلُّها بيدِ الله للمؤمنين؛ فوالِ اللهَ وحده وارجُ ثوابه، فولايتُه خيرُ ثوابٍ وأحسنُ عاقبة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحق"],"heart_state":{"text":"إفرادُ الله بالولاية، ورجاءُ حسنِ عاقبته."},"action":{"text":"اجعل ولاءك ونصرتك مطلوبةً من الله وحده الحقّ، وارجُ ثوابه وحسنَ عاقبته، فهو خيرُ من يُثيب وخيرُ من تكون عنده العاقبة."}}]},{"title":"مثلُ الدنيا الزائل، والباقياتُ الصالحات","range":[45,46],"theme":"تشبيهُ الدنيا بنباتٍ يهيج فيصير هشيمًا، وأنّ الباقياتِ خيرٌ","verses":[{"n":45,"reflection":{"text":"«واضرب لهم مثل الحياة الدنيا كماء أنزلناه من السماء فاختلط به نبات الأرض فأصبح هشيما تذروه الرياح وكان الله على كل شيء مقتدرا»، واضرب لهم مثلَ الدنيا كماءٍ أنزلناه من السماء فنبت به الزرعُ وازدهر، ثم أصبح يابسًا متكسّرًا تفرّقه الرياح؛ وكان الله على كلِّ شيءٍ قادرًا؛ ففي هذا أنّ الدنيا سريعةُ الزوالِ كالنباتِ يهيج فيهلك، فلا تستحقّ أن يُبنى عليها الأمل؛ فلا تغترَّ بخضرةِ الدنيا، واعمل لِما يبقى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ سرعةِ زوالِ الدنيا، وعدمُ الاغترارِ بها."},"action":{"text":"تأمّل كيف يزهو النباتُ ثم يصير هشيمًا تذروه الرياح، كذلك دنياك؛ فلا تبنِ أملك عليها، واصرف همّك لِما يبقى عند الله."}},{"n":46,"reflection":{"text":"«المال والبنون زينة الحياة الدنيا والباقيات الصالحات خير عند ربك ثوابا وخير أملا»: المالُ والبنون زينةُ هذه الحياةِ الدنيا يُتمتَّع بها ثم تزول، والأعمالُ الصالحاتُ الباقيةُ خيرٌ عند ربّك ثوابًا وخيرٌ لصاحبها أملًا يرجوه؛ ففي هذا موازنةٌ بين زينةٍ فانيةٍ وعملٍ باقٍ، وترغيبٌ في تقديمِ الباقياتِ الصالحات (كالتسبيحِ والذكرِ والصلاةِ وكلِّ عملٍ صالح)؛ فاجعل زادك من الباقياتِ الصالحاتِ لا من زينةٍ تفنى.","source":"تفسير السعدي","grade":"ma'thur"},"names":["والباقيات الصالحات خير عند ربك"],"heart_state":{"text":"إيثارُ الباقياتِ الصالحاتِ على زينةِ الدنيا."},"action":{"text":"اجعل رأسَ مالك الباقياتِ الصالحات: ذكرًا وصلاةً وصدقةً وكلَّ عملٍ صالح، ولا يستغرقك المالُ والولدُ فإنهما زينةٌ تزول والصالحُ يبقى."}}]},{"title":"مشهدُ الحشرِ وعرضِ الكتاب","range":[47,49],"theme":"تسييرُ الجبالِ وحشرُ الخلقِ وعرضُهم على ربّهم، وكتابٌ لا يغادر صغيرة","verses":[{"n":47,"reflection":{"text":"«ويوم نسير الجبال وترى الأرض بارزة وحشرناهم فلم نغادر منهم أحدا»، واذكر يوم نسيّر الجبالَ عن أماكنها فتصير هباءً، وترى الأرضَ ظاهرةً بارزةً ليس عليها ما يواريها، وجمعنا الخلقَ للحسابِ فلم نترك منهم أحدًا؛ ففي هذا هولُ القيامةِ وشمولُ الحشرِ لكلِّ أحد؛ فاستعدَّ ليومٍ تُسيَّر فيه الجبالُ ولا يُترَك منه أحد، وحاسب نفسك قبل ذلك اليوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ الحشرِ والاستعدادُ له."},"action":{"text":"استحضر يومًا تُسيَّر فيه الجبالُ وتُجمَع فيه الخلائقُ فلا يُترَك أحد، وحاسب نفسك اليومَ قبل أن تُحاسَب، واستعدَّ للعرضِ على ربّك."}},{"n":48,"reflection":{"text":"«وعرضوا على ربك صفا لقد جئتمونا كما خلقناكم أول مرة بل زعمتم ألن نجعل لكم موعدا»، وعُرِضوا على ربّك مصطفّين لا يخفى منهم أحد، يقال لهم: لقد جئتمونا فرادى حفاةً عراةً كما خلقناكم أوّلَ مرة، بل زعمتم أن لن نجعل لكم موعدًا للبعثِ والجزاء؛ ففي هذا تحقّقُ البعثِ الذي أنكروه، وأنّ العبدَ يعود كما بدأ مجرَّدًا من كلِّ شيء؛ فتذكّر أنك ستُعرَض على الله فردًا مجرَّدًا، فأعدَّ لذلك العرضِ عملك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ العرضِ على الله فردًا مجرَّدًا من كلِّ شيء."},"action":{"text":"تذكّر أنك تُعرَض على ربّك فردًا كما خُلِقت أوّلَ مرة، لا مالَ ولا نفرَ معك، إلا عملك؛ فجرّد نفسك للطاعةِ وأخلص لله قبل ذلك اليوم."}},{"n":49,"reflection":{"text":"«ووضع الكتاب فترى المجرمين مشفقين مما فيه ويقولون يا ويلتنا مال هذا الكتاب لا يغادر صغيرة ولا كبيرة إلا أحصاها ووجدوا ما عملوا حاضرا ولا يظلم ربك أحدا»، ووُضِعت كتبُ الأعمال، فترى المجرمين خائفين ممّا فيها، يقولون: يا هلاكَنا! ما لهذا الكتابِ لا يترك ذنبًا صغيرًا ولا كبيرًا إلا أحصاه وضبطه، ووجدوا كلَّ ما عملوا حاضرًا مكتوبًا، ولا يظلم ربّك أحدًا؛ ففي هذا إثباتُ إحصاءِ الأعمالِ كلِّها وعدلِ الله التامّ؛ فراقب عملك فكلُّه محصًى، واعلم أنك تجده حاضرًا، فلا تحتقر صغيرةً ولا كبيرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ولا يظلم ربك أحدا"],"heart_state":{"text":"مراقبةُ العملِ لعلمِ إحصائه، والطمأنينةُ إلى عدلِ الله."},"action":{"text":"راقب صغيرَ عملك وكبيرَه فكلُّه محصًى ستجده حاضرًا يوم القيامة؛ ولا تحتقر ذنبًا صغيرًا ولا حسنةً صغيرة، واطمئن إلى أنّ ربّك لا يظلم أحدًا."}}]},{"title":"عداوةُ إبليسَ وذريّته، وعجزُ الشركاء","range":[50,53],"theme":"التحذيرُ من موالاةِ الشيطانِ العدوّ، وتبرّؤُ الشركاءِ من عابديهم","verses":[{"n":50,"reflection":{"text":"«وإذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس كان من الجن ففسق عن أمر ربه أفتتخذونه وذريته أولياء من دوني وهم لكم عدو بئس للظالمين بدلا»، واذكر إذ أمرنا الملائكةَ بالسجودِ لآدم فسجدوا إلا إبليسَ كان من الجنِّ فخرج عن طاعةِ ربّه؛ أفتتّخذونه وذريّته أولياءَ من دوني وهم أعداءٌ لكم؟ بئس للظالمين هذا الاستبدالُ: الشيطانَ بدلًا من الرحمن؛ ففي هذا التحذيرُ من موالاةِ الشيطانِ الذي أظهر عداوته من أول الخلق؛ فعادِ الشيطانَ ولا تُطعه، فكيف تتّخذ عدوَّك وليًّا من دونِ ربّك؟","source":"تفسير السعدي","grade":"ma'thur"},"names":["وهم لكم عدو"],"heart_state":{"text":"الحذرُ من موالاةِ الشيطانِ العدوّ واتّخاذِه وليًّا."},"action":{"text":"اتّخذ الشيطانَ عدوًّا كما هو عدوٌّ لك، ولا تُطعه في شيء؛ فمن أطاع الشيطانَ فقد والى عدوَّه واستبدل الذي هو أدنى بالذي هو خير."}},{"n":51,"reflection":{"text":"«ما أشهدتهم خلق السماوات والأرض ولا خلق أنفسهم وما كنت متخذ المضلين عضدا»: ما أحضرتُ هؤلاء الشركاءَ (الشياطينَ) خلقَ السماواتِ والأرض، ولا خلقَ بعضهم بعضًا، فلا شركةَ لهم في الخلقِ ولا استحقاقَ للعبادة، وما كنتُ متّخذَ المضلّين أعوانًا؛ ففي هذا نفيُ كلِّ شركةٍ لغيرِ الله في الخلق، فكيف يُعبَد من لا يخلق؟ فأفرد الخالقَ بالعبادة، ولا تعبد من لا يملك خلقًا ولا نفعًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الخالقِ بالعبادةِ ونفيُ الشركةِ عمّن سواه."},"action":{"text":"أفرِد بعبادتك من خلق السماواتِ والأرضَ وخلقك، ولا تعبد من لا يقدر على خلقِ شيءٍ ولا يملك لك نفعًا؛ فالعبادةُ حقُّ الخالقِ وحده."}},{"n":52,"reflection":{"text":"«ويوم يقول نادوا شركائي الذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا»، واذكر يوم يقول الله للمشركين: نادوا شركائي الذين زعمتموهم لينصروكم، فيدعونهم فلا يجيبونهم، وجعلنا بينهم مهلكًا يشتركون فيه؛ ففي هذا فضيحةُ الشركِ يوم القيامةِ وخذلانُ المعبوداتِ لعابديها؛ فلا تعلّق قلبك بمن يخذلك يوم حاجتك، وأخلص دعاءك لله الذي يجيب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ لله، والحذرُ من التعلّقِ بمن يخذل."},"action":{"text":"لا تعلّق رجاءك ودعاءك بمخلوقٍ يخذلك أحوجَ ما تكون إليه، بل ادعُ الله وحده الذي يستجيب؛ فكلُّ معبودٍ سواه يتبرّأ من عابده يوم القيامة."}},{"n":53,"reflection":{"text":"«ورأى المجرمون النار فظنوا أنهم مواقعوها ولم يجدوا عنها مصرفا»، ورأى المجرمون النارَ فأيقنوا أنهم واقعون فيها، ولم يجدوا عنها معدلًا يصرفهم؛ ففي هذا تصويرُ يقينِ المجرمِ بالعذابِ حين لا مهرب، وأنّ النارَ حقٌّ يراها أهلها؛ فاعمل اليومَ على صرفِ نفسك عنها بالتوبةِ والطاعة قبل أن تراها ولا مصرف.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ حقيقةِ النارِ والعملُ على النجاةِ منها."},"action":{"text":"اعمل اليومَ على صرفِ نفسك عن النارِ بالتوبةِ وترْكِ المعاصي، قبل يومٍ يراها المجرمون فيوقنون الوقوعَ فيها ولا يجدون عنها مصرفًا."}}]},{"title":"جدلُ الإنسان، وسعةُ حلمِ الله","range":[54,59],"theme":"تصريفُ الأمثالِ وإعراضُ المكذّبين، ومغفرةُ الله وإمهالُه","verses":[{"n":54,"reflection":{"text":"«ولقد صرفنا في هذا القرآن للناس من كل مثل وكان الإنسان أكثر شيء جدلا»، ولقد نوّعنا في هذا القرآنِ للناسِ من كلِّ مثلٍ ليتّعظوا، وكان الإنسانُ أكثرَ المخلوقاتِ جدالًا ومخاصمةً بالباطل؛ ففي هذا بيانُ كمالِ حجّةِ القرآنِ وتنوّعِ أمثاله، وذمُّ الجدالِ بالباطلِ إعراضًا عن الحقّ؛ فاتّعظ بأمثالِ القرآنِ ولا تكن ممّن يجادل فيه بالباطل، فالخصامُ في الحقِّ بعد وضوحه هلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بأمثالِ القرآن، وتركُ الجدالِ بالباطل."},"action":{"text":"تدبّر أمثالَ القرآنِ لتتّعظ بها، ودع الجدالَ بالباطلِ ومماراةَ الحقِّ بعد وضوحه؛ فالإنسانُ أكثرُ شيءٍ جدلًا، والمؤمنُ يُسلِّم للحقّ."}},{"n":55,"reflection":{"text":"«وما منع الناس أن يؤمنوا إذ جاءهم الهدى ويستغفروا ربهم إلا أن تأتيهم سنة الأولين أو يأتيهم العذاب قبلا»، وما منع الناسَ من الإيمانِ والاستغفارِ حين جاءهم الهدى إلا عنادُهم وطلبُهم أن ينزل بهم عذابُ الأممِ السابقةِ أو يأتيهم العذابُ عِيانًا؛ ففي هذا ذمُّ من يؤخّر الإيمانَ والتوبةَ حتى يعاين العذاب، فلا ينفعه حينئذ؛ فبادر بالإيمانِ والاستغفارِ عند بلوغِ الهدى، ولا تنتظر العذابَ لتؤمن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ والاستغفارِ عند بلوغِ الهدى."},"action":{"text":"بادر بالإيمانِ والتوبةِ والاستغفارِ متى بلغك الهدى، ولا تؤخّرهما حتى تعاين العذاب فلا ينفعك؛ فالتسويفُ في التوبةِ من أعظمِ الخذلان."}},{"n":56,"reflection":{"text":"«وما نرسل المرسلين إلا مبشرين ومنذرين ويجادل الذين كفروا بالباطل ليدحضوا به الحق واتخذوا آياتي وما أنذروا هزوا»، وما نرسل الرسلَ إلا مبشّرين بالثوابِ ومنذرين من العقاب، ويجادل الكفارُ بالباطلِ ليبطلوا به الحقّ، واتّخذوا آياتي وإنذاري سخريةً واستهزاءً؛ ففي هذا بيانُ وظيفةِ الرسلِ وذمُّ من يقابل الحقَّ بالجدالِ والاستهزاء؛ فتلقَّ آياتِ الله بالتعظيمِ لا بالاستهزاء، واحذر مجادلةَ الباطلِ لإبطالِ الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله، والحذرُ من الاستهزاءِ بها."},"action":{"text":"تلقَّ آياتِ الله ووعيدَه بالتعظيمِ والقبول، ولا تجادل بالباطلِ لتردّ الحقّ، واحذر أشدَّ الحذرِ من الاستهزاءِ بشيءٍ من دينِ الله."}},{"n":57,"reflection":{"text":"«ومن أظلم ممن ذكر بآيات ربه فأعرض عنها ونسي ما قدمت يداه إنا جعلنا على قلوبهم أكنة أن يفقهوه وفي آذانهم وقرا وإن تدعهم إلى الهدى فلن يهتدوا إذا أبدا»، ولا أحدَ أظلمُ ممّن وُعِظ بآياتِ ربّه فأعرض عنها ونسي ما اقترفت يداه من الذنوب، إنا جعلنا على قلوبهم أغطيةً تمنعهم فهمَه وفي آذانهم صممًا (جزاءَ إعراضهم)، وإن تدعهم إلى الهدى فلن يهتدوا أبدًا؛ ففي هذا أنّ الإعراضَ عن الآياتِ أعظمُ الظلمِ وسببُ الطبعِ على القلب؛ فاحذر الإعراضَ عن التذكيرِ لئلا يُطبَع على قلبك، وأقبل على آياتِ الله بقلبٍ حاضر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإعراضِ عن الآياتِ لئلا يُطبَع على القلب."},"action":{"text":"أقبل على آياتِ الله كلّما ذُكِّرتَ بها بقلبٍ حاضرٍ خاشع، ولا تُعرِض عنها ولا تنسَ ذنوبك؛ فالإعراضُ عن التذكيرِ أظلمُ الظلمِ وسببُ حرمانِ الهدى."}},{"n":58,"reflection":{"text":"«وربك الغفور ذو الرحمة لو يؤاخذهم بما كسبوا لعجل لهم العذاب بل لهم موعد لن يجدوا من دونه موئلا»، وربّك الغفورُ لمن تاب، ذو الرحمةِ الواسعة، لو يؤاخذ المعرضين بذنوبهم لعجّل لهم العذاب، لكنه يمهلهم رحمةً، بل لهم موعدٌ للجزاءِ لن يجدوا من دونه ملجأً؛ ففي هذا سعةُ مغفرةِ الله ورحمتِه وحلمِه في الإمهال، مع حتمِ الجزاء؛ فارجُ مغفرةَ ربّك وارجع إليه، ولا يغرّنك الإمهالُ فإنّ للجزاءِ موعدًا لا مفرّ منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغفور","ذو الرحمة"],"heart_state":{"text":"الرجاءُ في مغفرةِ الله ورحمته، مع عدمِ الاغترارِ بالإمهال."},"action":{"text":"ارجُ مغفرةَ ربّك الغفورِ ذي الرحمة وبادر بالتوبةِ إليه، ولا يخدعنّك تأخّرُ العقوبة، فإنما هو حلمٌ وإمهال، وللجزاءِ موعدٌ لا ملجأَ منه."}},{"n":59,"reflection":{"text":"«وتلك القرى أهلكناهم لما ظلموا وجعلنا لمهلكهم موعدا»، وتلك القرى (كعادٍ وثمود) أهلكناهم حين ظلموا بالكفرِ والتكذيب، وجعلنا لهلاكهم وقتًا مضروبًا لا يتقدّم ولا يتأخّر؛ ففي هذا عبرةٌ بمصارعِ الظالمين، وأنّ الإهلاكَ يقع في أجلٍ مقدّر؛ فاعتبر بمن أُهلِكوا بظلمهم، واحذر الظلمَ، واعلم أنّ لكلِّ أمرٍ أجلًا عند الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الظالمين، والحذرُ من الظلم."},"action":{"text":"اعتبر بالقرى التي أهلكها الله بظلمها، واجتنب الظلمَ في حقِّ الله وحقِّ الخلق؛ واعلم أنّ الله يمهل الظالمَ إلى أجلٍ مضروب، ثم يأخذه."}}]},{"title":"رحلةُ موسى طلبًا للعلم","range":[60,64],"theme":"عزمُ موسى على بلوغِ مجمعِ البحرين، وعلامةُ الحوتِ على موضعِ اللقاء","verses":[{"n":60,"reflection":{"text":"«وإذ قال موسى لفتاه لا أبرح حتى أبلغ مجمع البحرين أو أمضي حقبا»، واذكر إذ قال موسى لخادمه يوشعَ بن نون: لا أزال أسير حتى أبلغ ملتقى البحرين حيث وُعِدتُ لقاءَ العبدِ الصالح، أو أمضيَ زمنًا طويلًا؛ ففي هذا عزمُ موسى ﷺ ــ وهو كليمُ الله ــ على الرحلةِ في طلبِ العلمِ مهما طال الطريق؛ فاطلب العلمَ ولو بعدت المسافةُ وطال السفر، فرحلةُ العلمِ شرفٌ اقتدى فيها موسى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرغبةُ في طلبِ العلمِ والصبرُ على مشقّته."},"action":{"text":"اطلب العلمَ النافعَ ولو بعدت المسافةُ وطال الطريق، واقتدِ بموسى الكليمِ الذي رحل يطلب علمًا عند من هو أعلمُ منه في بابه؛ فالعلمُ يُطلَب لا يُنتظَر."}},{"n":61,"reflection":{"text":"«فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله في البحر سربا»: فلما بلغا ملتقى البحرين نسيا الحوتَ الذي جعله الله علامةً، فأحياه الله فاتّخذ طريقه في البحرِ سربًا عجيبًا؛ ففي هذا أنّ الله يجعل للأمورِ علاماتٍ يهدي بها عبده، وأنّ آيةَ اللقاءِ كانت في حياةِ الحوت؛ فتأمّل كيف يسوق الله عبده إلى مقصوده بالعلاماتِ والأقدار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في تدبيرِ الله وسَوقِه العبدَ إلى مقصوده."},"action":{"text":"تأمّل كيف يهيّئ الله لك علاماتِ الطريقِ إلى الخير وأنت لا تشعر؛ فامضِ في طلبِ الحقِّ واثقًا أنّ الله يسوقك إلى مقصودك بأقداره ولطفه."}},{"n":62,"reflection":{"text":"«فلما جاوزا قال لفتاه آتنا غداءنا لقد لقينا من سفرنا هذا نصبا»: فلما جاوزا موضعَ اللقاء قال موسى لخادمه: أحضر طعامَ غدائنا، لقد لقينا من سفرنا هذا تعبًا؛ ففي هذا أنّ موسى لم يجد النَّصَبَ إلا بعد أن جاوز الموضعَ المقصود (لأنّ فقدَ البركةِ يورث التعب)، وفيه بشريةُ الأنبياءِ يصيبهم الجوعُ والتعب؛ فلا تستنكف أن تطلب حاجتك، واعلم أنّ مجاوزةَ المقصودِ تورث النَّصَب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ بالحاجةِ البشرية، والانتباهُ لأثرِ مفارقةِ الخير."},"action":{"text":"اطلب حاجتك من طعامٍ وراحةٍ بلا حرج، فالأنبياءُ نالهم التعب؛ وانتبه أنّ التعبَ قد يعقب مجاوزةَ موضعِ الخير، فتنبّه لعلاماتِ ربّك في طريقك."}},{"n":63,"reflection":{"text":"«قال أرأيت إذ أوينا إلى الصخرة فإني نسيت الحوت وما أنسانيه إلا الشيطان أن أذكره واتخذ سبيله في البحر عجبا»: قال الخادم: أتذكر إذ لجأنا إلى الصخرةِ فإني نسيتُ أمرَ الحوت، وما أنساني ذكرَه إلا الشيطان، وقد اتّخذ الحوتُ طريقه في البحرِ على وجهٍ عجيب؛ ففي هذا أنّ النسيانَ قد يكون من تلبيسِ الشيطان، وأنّ الآياتِ تُنسى بغفلة؛ فاستعذ بالله من الشيطانِ الذي يُنسي الخير، واحرص على ذكرِ ما ينفعك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعاذةُ من الشيطانِ الذي يُنسي، والحرصُ على الذكر."},"action":{"text":"استعذ بالله من الشيطانِ الذي يُنسيك الخيرَ وذكرَ الله، واعتنِ بحفظِ ما ينفعك من العلمِ والأمر؛ فالغفلةُ عن مواطنِ الخيرِ من كيدِ الشيطان."}},{"n":64,"reflection":{"text":"«قال ذلك ما كنا نبغ فارتدا على آثارهما قصصا»: قال موسى: ذلك الموضعُ الذي فُقِد فيه الحوتُ هو ما كنا نطلب، فرجعا يتتبّعان طريقهما الذي جاءا منه؛ ففي هذا حرصُ موسى على بلوغِ مقصوده فرجع فورًا إلى العلامة، وفيه أنّ طالبَ الحقِّ يعود إلى أثرِ الهدى ولا يفرّط فيه؛ فإذا لاحت لك علامةُ الخيرِ فبادر إليها ولا تفرّط، واقتفِ أثرَ الهدى بحرص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على اقتفاءِ أثرِ الهدى والمبادرةِ إليه."},"action":{"text":"إذا تبيّنت لك علامةُ الخيرِ والحقّ فبادر إلى اقتفائها ولا تفرّط، كما رجع موسى مسرعًا يقصّ أثره؛ فطالبُ الحقِّ لا يضيّع دليلًا يُوصِله إليه."}}]},{"title":"لقاءُ الخضرِ وأدبُ طلبِ العلم","range":[65,70],"theme":"العبدُ الصالحُ المؤتَى علمًا لدنيًّا، وتأدّبُ موسى في طلبِ التعلّم","verses":[{"n":65,"reflection":{"text":"«فوجدا عبدا من عبادنا آتيناه رحمة من عندنا وعلمناه من لدنا علما»: فوجدا عبدًا صالحًا من عبادنا (هو الخضر) آتيناه رحمةً من عندنا، وعلّمناه من لدنّا علمًا خاصًّا (من علمِ الغيبِ وأسرارِ الأقدار)؛ ففي هذا أنّ العلمَ فضلٌ من الله يؤتيه من يشاء، وأنّ فوقَ كلِّ ذي علمٍ عليم؛ فتواضع في علمك، واعلم أنّ العلمَ منحةٌ من الله لا تُنال إلا بتوفيقه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["آتيناه رحمة من عندنا","علمناه من لدنا علما"],"heart_state":{"text":"التواضعُ في العلم، والعلمُ بأنه منحةٌ من الله."},"action":{"text":"تواضع في علمك مهما بلغت، فقد رحل موسى الكليمُ ليتعلّم ممّن آتاه الله علمًا خاصًّا؛ واعلم أنّ العلمَ رحمةٌ يؤتيها الله من يشاء، فاطلبها منه."}},{"n":66,"reflection":{"text":"«قال له موسى هل أتبعك على أن تعلمن مما علمت رشدا»: قال موسى للخضرِ بتلطّفٍ وتواضع: هل أصحبك وأتّبعك على أن تعلّمني ممّا علّمك الله رشدًا وهدًى؟ ففي هذا أدبُ المتعلّمِ مع معلّمه: الاستئذانُ والتواضعُ وإظهارُ الحاجة، وموسى نبيٌّ كليمٌ يخاطب هكذا؛ فتأدّب مع معلّمك واطلب العلمَ بتواضعٍ ولين، فذلك سبيلُ الانتفاع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأدّبُ مع المعلّمِ وطلبُ العلمِ بتواضع."},"action":{"text":"تأدّب مع من تتعلّم منه، واطلب العلمَ بلينٍ وتواضعٍ واستئذانٍ كما فعل موسى؛ فالكِبرُ يحرم العلم، والتواضعُ بابُ الانتفاعِ به."}},{"n":67,"reflection":{"text":"«قال إنك لن تستطيع معي صبرا»: قال الخضر: إنك يا موسى لن تقدر على الصبرِ على ما ترى منّي؛ ففي هذا أنّ العلمَ الذي لم يُحَط به يشقّ الصبرُ عليه، وأنّ المعلّمَ يبيّن للمتعلّمِ ما يحتاجه من الصبر؛ فاستعدَّ للصبرِ في طلبِ العلمِ فإنه لا يُنال براحةِ الجسد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للصبرِ في طلبِ العلم."},"action":{"text":"استعدَّ للصبرِ على مشقّةِ العلمِ وما يخفى عليك من حِكَمه، فالعلمُ لا يُنال بالراحة؛ ووطّن نفسك على الصبرِ حتى يتبيّن لك وجهُ الحقّ."}},{"n":68,"reflection":{"text":"«وكيف تصبر على ما لم تحط به خبرا»، وكيف تصبر على أمورٍ ظاهرها منكرٌ وأنت لم تعلم باطنها وحكمتها؟ ففي هذا أنّ العجلةَ بالإنكارِ تأتي من الجهلِ بالبواطن، وأنّ من لم يُحِط علمًا بالأمرِ لا يصبر عليه؛ فلا تحكم على ما لم تُحِط بعلمه، وتأنَّ حتى ينكشف لك وجهُ الحكمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأنّي وعدمُ الحكمِ على ما لم يُحَط بعلمه."},"action":{"text":"لا تعجل بإنكارِ ما لم تعلم باطنه وحكمته، فكثيرٌ ممّا تستنكره ظاهرًا له في الباطنِ حكمةٌ خفيت عليك؛ فتأنَّ في الحكمِ حتى ينكشف الأمر."}},{"n":69,"reflection":{"text":"«قال ستجدني إن شاء الله صابرا ولا أعصي لك أمرا»: قال موسى: ستجدني إن شاء الله صابرًا على ما أرى، ولا أخالف لك أمرًا تأمرني به؛ ففي هذا تعليقُ الصبرِ بمشيئةِ الله (فلم يجزم بقدرته)، والتزامُ طاعةِ المعلّمِ في المعروف؛ فعلّق عزمك على الصبرِ بمشيئةِ الله، والتزم طاعةَ من تتعلّم منه فيما يأمرك من الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إن شاء الله"],"heart_state":{"text":"تعليقُ الصبرِ بمشيئةِ الله، والتزامُ طاعةِ المعلّم."},"action":{"text":"علّق كلَّ عزمٍ على الصبرِ والطاعةِ بمشيئةِ الله «إن شاء الله»، والتزم بما يرشدك إليه معلّمك من الحقّ؛ فبمشيئةِ الله وحدها يثبت العبدُ ويصبر."}},{"n":70,"reflection":{"text":"«قال فإن اتبعتني فلا تسألني عن شيء حتى أحدث لك منه ذكرا»: قال الخضر: فإن صحبتني فلا تسألني عن شيءٍ تستنكره حتى أكون أنا الذي أبتدئك ببيانه؛ ففي هذا أدبٌ من آدابِ التعلّم: أن يترك المتعلّمُ العجلةَ بالسؤالِ حتى يبيّن له المعلّم في وقته المناسب؛ فتأدّب في تلقّي العلم، ولا تعجل بالاعتراضِ حتى يبلغك البيان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ العجلةِ في السؤالِ والاعتراضِ عند التعلّم."},"action":{"text":"تأدّب في التعلّمِ فلا تعجل بالاعتراضِ أو السؤالِ عمّا تستنكر، بل انتظر حتى يبيّن لك المعلّمُ الحكمةَ في وقتها؛ فالعجلةُ تحرم الفائدةَ والصحبة."}}]},{"title":"الحوادثُ الثلاثةُ ومفارقةُ موسى للخضر","range":[71,78],"theme":"خرقُ السفينةِ وقتلُ الغلامِ وإقامةُ الجدار، وعجزُ موسى عن الصبر","verses":[{"n":71,"reflection":{"text":"«فانطلقا حتى إذا ركبا في السفينة خرقها قال أخرقتها لتغرق أهلها لقد جئت شيئا إمرا»: فمضيا حتى ركبا سفينةً، فخرقها الخضرُ، فأنكر موسى قائلًا: أخرقتها لتُغرِق أهلها؟ لقد جئت شيئًا منكرًا عظيمًا؛ ففي هذا أنّ ظاهرَ الفعلِ قد يكون منكرًا وباطنُه رحمة، وأنّ موسى بادر بالإنكارِ لغيرةِ إيمانه؛ فلا تعجل بالحكمِ على ظاهرِ الأمرِ قبل أن تعلم باطنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"كفُّ العجلةِ عن الحكمِ على ظاهرِ الأمر."},"action":{"text":"لا تعجل بإنكارِ ما تراه منكرًا في ظاهره حتى تعلم حقيقته وحكمته؛ فكثيرٌ ممّا ظاهرُه شرٌّ يخفي رحمةً، كخرقِ السفينةِ الذي كان نجاةً لأهلها."}},{"n":72,"reflection":{"text":"«قال ألم أقل إنك لن تستطيع معي صبرا»: قال الخضر مذكّرًا: ألم أقل لك إنك لن تقدر على الصبرِ معي؟ ففي هذا تذكيرُ المعلّمِ للمتعلّمِ بشرطه عند أول مخالفة، برفقٍ لا بتعنيف؛ فتقبّل التذكيرَ إذا أخطأت، واصبر على ما التزمت به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ التذكيرِ عند الخطأ والصبرُ على الالتزام."},"action":{"text":"إذا ذُكِّرت بخطئك أو بشرطٍ التزمته فتقبّله بصدرٍ رحب، ولا تجادل؛ وجاهد نفسك على الوفاءِ بما عاهدت عليه من الصبرِ والطاعة."}},{"n":73,"reflection":{"text":"«قال لا تؤاخذني بما نسيت ولا ترهقني من أمري عسرا»: قال موسى معتذرًا: لا تؤاخذني بنسياني لشرطك، ولا تكلّفني في صحبتي إياك مشقّةً وعسرًا؛ ففي هذا أدبُ الاعتذارِ عن الخطأ وطلبُ التيسير، وأنّ النسيانَ عذرٌ يُعتذَر به؛ فإذا أخطأت فاعتذر بأدب، والتمس العذرَ لغيرك واليُسرَ في معاملته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتذارُ بأدبٍ عند الخطأ، وطلبُ اليُسر."},"action":{"text":"إذا أخطأت أو نسيت فبادر بالاعتذارِ بأدبٍ ولين، والتمس من إخوانك اليُسرَ لا العُسر؛ فالنسيانُ معفوٌّ عنه، والرفقُ في المعاملةِ من خُلقِ المؤمن."}},{"n":74,"reflection":{"text":"«فانطلقا حتى إذا لقيا غلاما فقتله قال أقتلت نفسا زكية بغير نفس لقد جئت شيئا نكرا»: فمضيا حتى لقيا غلامًا فقتله الخضر، فأنكر موسى بشدّةٍ: أقتلت نفسًا طاهرةً لم تقتل أحدًا؟ لقد جئت شيئًا منكرًا فظيعًا؛ ففي هذا شدّةُ إنكارِ موسى لِما ظاهرُه أعظمُ من الأول، وغيرتُه لحدودِ الله؛ فالغيرةُ على الحقِّ محمودة، لكنّ العلمَ بالبواطنِ يكشف حِكمًا خفية، فلا تقطع بالحكمِ قبل تمامِ العلم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الغيرةُ على حدودِ الله مع التوقّفِ حتى يتبيّن الباطن."},"action":{"text":"لتكن لك غيرةٌ على محارمِ الله كغيرةِ موسى، لكن لا تقطع بالحكمِ على ما خفيت عليك حقيقته؛ فوراءَ بعضِ الظواهرِ المُنكَرةِ حِكَمٌ يعلمها الله وحده."}},{"n":75,"reflection":{"text":"«قال ألم أقل لك إنك لن تستطيع معي صبرا»: قال الخضر مؤكّدًا بزيادةِ «لك»: ألم أقل لك إنك لن تستطيع معي صبرًا؟ ففي هذا تأكيدُ التذكيرِ عند تكرارِ المخالفة، وأنّ العهدَ يُذكَّر به مرةً بعد مرة؛ فراجع نفسك عند تكرارِ الخطأ، ولا تلم إلا نفسك إذا نُبِّهت مرارًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ عند تكرارِ الخطأ."},"action":{"text":"إذا تكرّر منك الخطأ بعد التذكيرِ فحاسب نفسك ولا تعتب على من نبّهك؛ فتكرارُ الزلّةِ يستوجب مراجعةً أعمقَ للنفسِ وعزمًا أصدقَ على الوفاء."}},{"n":76,"reflection":{"text":"«قال إن سألتك عن شيء بعدها فلا تصاحبني قد بلغت من لدني عذرا»: قال موسى: إن سألتك عن شيءٍ بعد هذه المرة فارفض صحبتي، فقد بلغت العذرَ في مفارقتي؛ ففي هذا إنصافُ موسى من نفسه واعترافُه بأنه استنفد عذره، وفيه أنّ للصحبةِ حدًّا يُنهيها إخلالُ أحدهما بشرطها؛ فكن منصفًا من نفسك، واعترف بحقِّ صاحبك إذا أخللتَ بالعهد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنصافُ من النفسِ والاعترافُ بحقِّ الصاحب."},"action":{"text":"كن منصفًا من نفسك كما أنصف موسى، واعترف بخطئك إذا أخللت بعهدك مع صاحبك؛ فالإنصافُ من النفسِ خُلقُ الكبارِ وأهلِ الإيمان."}},{"n":77,"reflection":{"text":"«فانطلقا حتى إذا أتيا أهل قرية استطعما أهلها فأبوا أن يضيفوهما فوجدا فيها جدارا يريد أن ينقض فأقامه قال لو شئت لاتخذت عليه أجرا»: فمضيا حتى أتيا أهلَ قريةٍ فطلبا منهم طعامًا فبخلوا ولم يضيّفوهما، فوجدا فيها جدارًا مائلًا يوشك أن يسقط فأقامه الخضرُ وأصلحه، قال موسى: لو شئت لأخذت على عملك أجرًا نأكل به؛ ففي هذا لؤمُ أهلِ القرية في منعِ الضيافة، ومقابلةُ الخضرِ الإساءةَ بالإحسان؛ فقابل الإساءةَ بالإحسان، ولا تمنعك إساءةُ الناسِ عن فعلِ المعروف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مقابلةُ الإساءةِ بالإحسان، وبذلُ المعروفِ لمن منعه."},"action":{"text":"لا تمنعك إساءةُ الناسِ إليك عن فعلِ الخيرِ معهم، واصنع المعروفَ ولو لمن بخل عليك، كما أقام الخضرُ جدارَ من أبَوا ضيافته؛ فالإحسانُ خُلقٌ لا يُقابَل بمثلِ الإساءة."}},{"n":78,"reflection":{"text":"«قال هذا فراق بيني وبينك سأنبئك بتأويل ما لم تستطع عليه صبرا»: قال الخضر: هذا وقتُ الفراقِ بيننا كما شرطتَ على نفسك، وسأخبرك بتفسيرِ الأفعالِ التي لم تصبر على رؤيتها؛ ففي هذا وفاءُ الخضرِ ببيانِ الحكمةِ عند الفراق، وأنّ لكلِّ صحبةٍ أجلًا؛ فتعلّم أنّ وراءَ الأقدارِ حِكَمًا ستنكشف، واصبر حتى يبيّن الله لك تأويلها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["هذا فراق بيني وبينك"],"heart_state":{"text":"الثقةُ بأنّ وراءَ الأقدارِ حِكَمًا ستنكشف."},"action":{"text":"اصبر على ما يخفى عليك من أقدارِ الله، واثقًا أنّ وراءها حِكَمًا سينكشف بعضُها في الدنيا وتمامُها في الآخرة؛ فما كلُّ حكمةٍ تُدرَك في حينها."}}]},{"title":"تأويلُ الأفعالِ الثلاثة: حِكمةُ القدر","range":[79,82],"theme":"كشفُ الخضرِ لحِكَمِ خرقِ السفينةِ وقتلِ الغلامِ وإقامةِ الجدار","verses":[{"n":79,"reflection":{"text":"«أما السفينة فكانت لمساكين يعملون في البحر فأردت أن أعيبها وكان وراءهم ملك يأخذ كل سفينة غصبا»: أما السفينةُ فكانت لمساكينَ يعملون في البحرِ يرتزقون منها، فأردت أن أجعل فيها عيبًا (بالخرق) لتنجوَ من ملكٍ ظالمٍ أمامهم يأخذ كلَّ سفينةٍ صالحةٍ غصبًا؛ ففي هذا أنّ الضررَ اليسيرَ قد يُدفَع به ضررٌ أكبر، وأنّ ما ظاهرُه إفسادٌ قد يكون حفظًا؛ فاعلم أنّ في بعضِ المصائبِ الصغيرةِ نجاةً من كبيرة، فارضَ بقدرِ الله وأحسن الظنَّ به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بقدرِ الله وإحسانُ الظنِّ بحكمته في المصائب."},"action":{"text":"إذا أصابك ضررٌ يسير فتذكّر أنه قد يدفع عنك أكبرَ منه، كما عِيبت السفينةُ لتسلمَ من الغصب؛ فارضَ بقدرِ الله وأحسن الظنَّ بحكمته فيما يسوقه إليك."}},{"n":80,"reflection":{"text":"«وأما الغلام فكان أبواه مؤمنين فخشينا أن يرهقهما طغيانا وكفرا»، وأما الغلامُ فكان أبواه مؤمنين، فخشينا (علمنا بإعلامِ الله) أن يحملهما حبُّه على متابعته في الطغيانِ والكفر، وقد كُتِب كافرًا؛ ففي هذا أنّ الله قد يقبض نفسًا صغيرةً حمايةً لأبويها من فتنةٍ في دينهما، وأنّ حكمته بالغةٌ فيما يقضي؛ فسلّم لله في أقداره، فقد يأخذ ما تحبّ رحمةً بك من حيث لا تعلم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله في أقداره، والعلمُ بأنّ فيها رحمةً خفية."},"action":{"text":"سلّم لحكمِ الله فيما يأخذ ويعطي، واعلم أنه قد يمنعك محبوبًا أو يقبض عزيزًا رحمةً بدينك وعاقبتك؛ فحسنُ الظنِّ بالله بابُ الطمأنينةِ عند الأقدار."}},{"n":81,"reflection":{"text":"«فأردنا أن يبدلهما ربهما خيرا منه زكاة وأقرب رحما»: فأردنا أن يعوّضهما ربّهما بولدٍ خيرٍ منه صلاحًا وطهارةً وأبرَّ بهما وأرحم؛ ففي هذا أنّ الله إذا أخذ شيئًا عوّض عنه خيرًا منه لمن صبر ورضي، وأنّ حكمته اقترنت بالرحمة؛ فإذا فقدت محبوبًا فأمّل من الله خيرًا منه، فهو الذي يأخذ ليعطيَ أحسن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأملُ في عوضِ الله وخلفِه لمن صبر ورضي."},"action":{"text":"إذا فقدت عزيزًا أو محبوبًا فأمّل من ربّك عوضًا خيرًا منه، فهو الذي أبدل الأبوين خيرًا من ولدهما؛ فاصبر واحتسب، وثق أنّ عطاءَ الله خيرٌ وأبقى."}},{"n":82,"reflection":{"text":"«وأما الجدار فكان لغلامين يتيمين في المدينة وكان تحته كنز لهما وكان أبوهما صالحا فأراد ربك أن يبلغا أشدهما ويستخرجا كنزهما رحمة من ربك وما فعلته عن أمري ذلك تأويل ما لم تسطع عليه صبرا»، وأما الجدارُ فكان لغلامين يتيمين، وتحته كنزٌ (مالٌ) لهما، وكان أبوهما صالحًا، فأراد ربّك أن يبلغا رشدهما فيستخرجا كنزهما، رحمةً من ربّك بهما لصلاحِ أبيهما، وما فعلت ذلك من تلقاءِ نفسي بل بأمرِ الله؛ ذلك تأويلُ ما لم تصبر عليه؛ ففي هذا أنّ صلاحَ الأبِ يحفظ الله به ذريّته، وأنّ أفعالَ الخضرِ كلَّها بوحيٍ لا اجتهاد؛ فاصلح تُحفَظ في ذريّتك، وسلّم لله فإنّ رحمته سبقت في تدبيره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رحمة من ربك","وكان أبوهما صالحا"],"heart_state":{"text":"الطمعُ في حفظِ الله للذريّةِ بصلاحِ الوالد، والتسليمُ لتدبيره."},"action":{"text":"اصلح نفسك يحفظك الله في ذريّتك ومالك كما حُفِظ اليتيمان بصلاحِ أبيهما؛ وسلّم لتدبيرِ الله واعلم أنّ رحمته تسبق في كلِّ ما يقضي، وأنّ للأقدارِ تأويلًا حسنًا وإن خفي."}}]},{"title":"ذو القرنين: الملكُ العادلُ الممكَّن","range":[83,88],"theme":"تمكينُ الله لذي القرنين، وعدلُه في المغربِ بين الظالمِ والمحسن","verses":[{"n":83,"reflection":{"text":"«ويسألونك عن ذي القرنين قل سأتلو عليكم منه ذكرا»، ويسألك المشركون (بتلقينِ اليهود) عن خبرِ ذي القرنين، قل: سأقصّ عليكم من خبره ما فيه عبرةٌ وذكرى؛ ففي هذا أنّ القصصَ القرآنيَّ للعبرةِ لا للتسلية، وأنّ العلمَ يُلتمَس من مصدره الصادق؛ فاقرأ قصصَ القرآنِ للاتّعاظِ والذكرى لا لمجردِ الخبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التماسُ العبرةِ من قصصِ القرآن."},"action":{"text":"اقرأ قصصَ القرآنِ متلمّسًا العبرةَ والذكرى، لا مجردَ الحكايةِ والتسلية؛ فما قصّه الله علينا إلا لنعتبرَ ونعمل، فاجعل لكلِّ قصةٍ أثرًا في قلبك."}},{"n":84,"reflection":{"text":"«إنا مكنا له في الأرض وآتيناه من كل شيء سببا»: إنا مكّنّا لذي القرنين في الأرضِ ملكًا واسعًا، وأعطيناه من كلِّ ما يريده سببًا وطريقًا يوصله إليه؛ ففي هذا أنّ التمكينَ والأسبابَ من الله وحده، وأنّ من مكّنه الله فليشكر بالعملِ الصالح؛ فإذا آتاك الله قوةً أو سببًا فاستعمله في طاعته وإصلاحِ الأرض، فالتمكينُ منحةٌ ومسؤولية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ التمكينِ باستعمالِه في الطاعةِ والإصلاح."},"action":{"text":"إذا آتاك الله جاهًا أو قدرةً أو سببًا فاشكره باستعماله في الحقِّ وإصلاحِ الأرض ونفعِ الناس؛ فالتمكينُ أمانةٌ يُسأل عنها العبدُ لا مجردَ عطاء."}},{"n":85,"reflection":{"text":"«فأتبع سببا»: فسلك ذو القرنين سببًا وطريقًا ممّا آتاه الله موصلًا إلى مقصده نحو المغرب؛ ففي هذا الأخذُ بالأسبابِ مع التمكين، وأنّ العبدَ يسعى في الأرضِ بما يسّره الله له؛ فخذ بالأسبابِ التي هيّأها الله لك، ولا تقعد عن السعيِ اتّكالًا، فالتمكينُ يُثمر بالعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأخذُ بالأسبابِ والسعيُ مع الاعتمادِ على الله."},"action":{"text":"خذ بالأسبابِ المشروعةِ التي يسّرها الله لك واسعَ في الأرض، ولا تقعد متّكلًا؛ فذو القرنين مع تمكينِ الله له أتبع الأسبابَ وسعى، فالتوكّلُ سعيٌ لا قعود."}},{"n":86,"reflection":{"text":"«حتى إذا بلغ مغرب الشمس وجدها تغرب في عين حمئة ووجد عندها قوما قلنا يا ذا القرنين إما أن تعذب وإما أن تتخذ فيهم حسنا»: حتى إذا بلغ أقصى المغربِ رأى الشمسَ في نظره كأنها تغرب في عينٍ ذاتِ طينٍ أسود، ووجد عندها قومًا كفارًا، فألهمناه أو قلنا له: إما أن تعذّبهم وإما أن تحسن إليهم؛ ففي هذا أنّ الله ولّاه أمرَهم وخيّره في سياستهم بالعدل؛ فمن ولّاه الله أمرًا فليتحرَّ العدلَ والإحسانَ في رعيّته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحرّي العدلِ والإحسانِ فيمن ولّاك الله أمرهم."},"action":{"text":"إذا ولّاك الله أمرَ أحدٍ ــ أهلًا أو عملًا أو رعيّةً ــ فتحرَّ العدلَ في الحقّ والإحسانَ في المعاملة؛ فالسلطةُ اختبارٌ يُظهِر عدلَ العبدِ من جوره."}},{"n":87,"reflection":{"text":"«قال أما من ظلم فسوف نعذبه ثم يرد إلى ربه فيعذبه عذابا نكرا»: قال ذو القرنين: أما من ظلم بالكفرِ والفسادِ فسوف نعاقبه في الدنيا، ثم يُردّ إلى ربّه فيعذّبه في الآخرةِ عذابًا منكرًا شديدًا؛ ففي هذا إقامةُ العدلِ في الظالمِ وربطُ عقوبةِ الدنيا بعقوبةِ الآخرة؛ فأقم العدلَ على الظالمِ ولا تُهمله، واعلم أنّ وراءَ عقوبةِ الدنيا عذابَ الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إقامةُ العدلِ على الظالمِ واستحضارُ عذابِ الآخرة."},"action":{"text":"لا تُهمل الظالمَ بل خذ على يده بالعدل، واعلم أنّ عذابَ الدنيا لا يُغني عن عذابِ الآخرةِ إن لم يتب؛ فأقم الحقَّ ورهّب الظالمَ بمصيرِ الآخرة."}},{"n":88,"reflection":{"text":"«وأما من آمن وعمل صالحا فله جزاء الحسنى وسنقول له من أمرنا يسرا»، وأما من آمن وعمل صالحًا فله الجنةُ جزاءً حسنًا، وسنعامله بالرفقِ واليُسرِ في أمرنا؛ ففي هذا عدلُ ذي القرنين وإحسانُه: شدّةٌ على الظالمِ ولينٌ للمؤمن؛ فكن شديدًا على الظلمِ رحيمًا بالمحسنين، وارجُ الحسنى لمن آمن وأحسن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللينُ للمحسنِ ورجاءُ الحسنى له."},"action":{"text":"عامِل أهلَ الإيمانِ والإحسانِ باللينِ واليُسرِ لا بالغلظة، وبشّرهم بالحسنى؛ واجمع في معاملتك بين الشدّةِ على الظالمِ والرحمةِ بالمحسن، فذلك عدلُ الولاة."}}]},{"title":"مسيرُ ذي القرنين شرقًا وبناءُ السدّ","range":[89,98],"theme":"بلوغُه مطلعَ الشمس، وبناؤه الردمَ بين يأجوجَ ومأجوج، وردُّه الفضلَ لله","verses":[{"n":89,"reflection":{"text":"«ثم أتبع سببا»: ثم سلك ذو القرنين سببًا وطريقًا آخرَ يوصله نحو المشرق؛ ففي هذا مواصلةُ السعيِ في الخيرِ وعدمُ الاكتفاءِ بما مضى، وأنّ الهمّةَ العاليةَ لا تقف؛ فلا تقنع من الخيرِ بما بلغت، واصل السعيَ في نفعِ نفسك وغيرك ما دمت قادرًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"علوُّ الهمّةِ ومواصلةُ السعيِ في الخير."},"action":{"text":"لا تقنع من الخيرِ بما أنجزت بل واصل السعيَ فيه ما دمت قادرًا، فذو القرنين كلّما بلغ غايةً أتبعها بأخرى؛ فالهمّةُ العاليةُ في الطاعةِ والنفعِ لا تعرف التوقّف."}},{"n":90,"reflection":{"text":"«حتى إذا بلغ مطلع الشمس وجدها تطلع على قوم لم نجعل لهم من دونها سترا»: حتى إذا بلغ مطلعَ الشمسِ من جهةِ الشرقِ وجدها تطلع على قومٍ لم نجعل لهم من دون الشمسِ سترًا يقيهم (لا بناءَ ولا شجر)؛ ففي هذا سعةُ ملكِ الله واختلافُ أحوالِ الخلق، وأنّ من الناسِ من عاش في شدّةٍ وعُري؛ فتأمّل تنوّعَ خلقِ الله، واشكر ما ستر الله به حالك من نعمٍ لا تُحصى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ سترِ الله ونعمِه، والتأمّلُ في تنوّعِ خلقه."},"action":{"text":"اشكر الله على ما أسبغ عليك من سترٍ ومسكنٍ ولباسٍ ونعم، وتأمّل أحوالَ من هم دونك؛ فالنظرُ إلى من هو أقلَّ منك في الدنيا يورث الشكرَ والقناعة."}},{"n":91,"reflection":{"text":"«كذلك وقد أحطنا بما لديه خبرا»: كذلك كان أمرُ ذي القرنين، وقد أحطنا بكلِّ ما عنده من عُدّةٍ وجندٍ وعلمٍ علمًا تامًّا؛ ففي هذا إحاطةُ علمِ الله بكلِّ شيءٍ ظاهرِه وباطنه؛ فراقب اللهَ المحيطَ بأحوالك كلِّها، واعلم أنه لا يخفى عليه من أمرك شيء.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وقد أحطنا بما لديه خبرا"],"heart_state":{"text":"مراقبةُ الله المحيطِ علمُه بكلِّ شيء."},"action":{"text":"راقب اللهَ الذي أحاط بكلِّ شيءٍ خبرًا، فلا يخفى عليه سرُّك ولا علانيتك؛ ومن استحضر إحاطةَ علمِ الله استحيا أن يعصيه واطمأنّ إلى حفظه."}},{"n":92,"reflection":{"text":"«ثم أتبع سببا»: ثم سلك ذو القرنين سببًا وطريقًا ثالثًا يوصله إلى مقصدٍ جديد؛ ففي هذا دوامُ استعمالِ ما آتاه الله من الأسبابِ في الإصلاح، وأنّ صاحبَ الرسالةِ لا يفتر؛ فداوِم على استثمارِ ما أعطاك الله من قوّةٍ وقدرةٍ في الخيرِ والإصلاح، ولا يوهنك ما مضى عن قادمِ العمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"دوامُ استثمارِ نعمِ الله في الإصلاح."},"action":{"text":"داوِم على استعمالِ ما آتاك الله من قدرةٍ ووقتٍ ومالٍ في الإصلاحِ والنفع، ولا تفتر؛ فالمؤمنُ يستثمر عمره كلَّه في الخير، ينتقل من صالحٍ إلى أصلح."}},{"n":93,"reflection":{"text":"«حتى إذا بلغ بين السدين وجد من دونهما قوما لا يكادون يفقهون قولا»: حتى إذا بلغ بين الجبلين وجد من دونهما قومًا لا يكادون يفهمون كلامًا لعُجمتهم؛ ففي هذا بلوغُه أقاصيَ الأرضِ وتنوّعُ ألسنةِ الخلق، وأنّ التفاهمَ نعمةٌ من الله؛ فاشكر نعمةَ البيانِ والفهم، واصبر على تبليغِ الحقِّ لمن يعسر عليهم فهمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ البيان، والصبرُ في تبليغِ الحقّ."},"action":{"text":"اشكر نعمةَ الفهمِ والبيانِ التي حرمها كثيرٌ من الخلق، واصبر على تفهيمِ الحقِّ لمن يعسر عليهم إدراكه، والتمس لهم من الأساليبِ ما يقرّبهم إليه."}},{"n":94,"reflection":{"text":"«قالوا يا ذا القرنين إن يأجوج ومأجوج مفسدون في الأرض فهل نجعل لك خرجا على أن تجعل بيننا وبينهم سدا»: قال القومُ: يا ذا القرنين إنّ يأجوجَ ومأجوجَ يفسدون في الأرضِ بالقتلِ والنهب، فهل نجعل لك مالًا (جُعلًا) على أن تبنيَ بيننا وبينهم حاجزًا؟ ففي هذا التجاءُ الضعفاءِ إلى القويِّ العادلِ لدفعِ الفساد، وأنّ درءَ الفسادِ مطلبٌ مشروع؛ فأعِن الضعفاءَ على دفعِ الظلمِ عنهم، واسعَ في كفِّ الفسادِ في الأرض.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعانةُ الضعفاءِ والسعيُ في دفعِ الفسادِ عنهم."},"action":{"text":"أعِن الضعفاءَ والمظلومين على دفعِ من يفسد في الأرضِ ويؤذيهم، واسعَ في كفِّ الشرِّ عنهم بما تقدر؛ فحمايةُ الناسِ من الفسادِ من أعظمِ العملِ الصالح."}},{"n":95,"reflection":{"text":"«قال ما مكني فيه ربي خير فأعينوني بقوة أجعل بينكم وبينهم ردما»: قال ذو القرنين: ما أعطانيه ربّي من الملكِ والقدرةِ خيرٌ من مالكم، فأعينوني بقوّةِ الأبدانِ والعمل أبنِ بينكم وبينهم ردمًا حصينًا؛ ففي هذا عفّةُ ذي القرنين عن أموالِ الناسِ وردُّه الفضلَ لله، واستعانتُه بالعملِ لا بالمال؛ فاعفف عمّا في أيدي الناس، وردَّ فضلَ ما عندك لله، واطلب العونَ في الخيرِ بالعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العفّةُ عمّا في أيدي الناس، وردُّ الفضلِ لله."},"action":{"text":"اعفف عن أموالِ الناسِ ولا تستغلَّ حاجتهم إليك، وردَّ فضلَ ما آتاك الله إليه لا إلى نفسك؛ واطلب في مشاريعِ الخيرِ عونَ الأيدي العاملةِ قبل المال."}},{"n":96,"reflection":{"text":"«آتوني زبر الحديد حتى إذا ساوى بين الصدفين قال انفخوا حتى إذا جعله نارا قال آتوني أفرغ عليه قطرا»: قال: أحضروا لي قطعَ الحديد، حتى إذا سوّى بين جانبي الجبلين قال: انفخوا النارَ على الحديدِ حتى صار كالنار، قال: أحضروا لي نحاسًا مذابًا أصبّه عليه ليشتدَّ؛ ففي هذا إتقانُ العملِ وحسنُ التدبيرِ والأخذُ بالأسبابِ القويّة؛ فأتقن عملك وأحكمه، وخذ بأقوى الأسبابِ المشروعةِ في كلِّ ما تبنيه من خير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إتقانُ العملِ والأخذُ بالأسبابِ المُحكَمة."},"action":{"text":"أتقن كلَّ عملٍ تباشره وأحكمه، وخذ بأقوى الأسبابِ المشروعةِ فيه؛ فذو القرنين مع تمكينِ الله له لم يترك الإتقانَ والتدبير، فالتوكّلُ لا ينافي إحسانَ العمل."}},{"n":97,"reflection":{"text":"«فما اسطاعوا أن يظهروه وما استطاعوا له نقبا»: فما قدر يأجوجُ ومأجوجُ أن يعلوا السدَّ لارتفاعِه وملاسته، ولا أن يثقبوه من أسفلَ لصلابته؛ ففي هذا تمامُ الحفظِ الذي أجراه الله على يدِ عبده، وأنّ العملَ المتقنَ المبنيَّ على التوكّلِ يثمر؛ فاعمل بإتقانٍ وتوكّل، وثق أنّ الله يحفظ ما بُني على طاعته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ الله يحفظ العملَ المتقنَ المبنيَّ على طاعته."},"action":{"text":"اعمل بإتقانٍ متوكّلًا على الله، وثق أنّ ما بُني على الحقِّ والطاعةِ يحفظه الله ويبارك فيه؛ فثمرةُ العملِ بيدِ الله بعد بذلِ الأسباب."}},{"n":98,"reflection":{"text":"«قال هذا رحمة من ربي فإذا جاء وعد ربي جعله دكاء وكان وعد ربي حقا»: قال ذو القرنين عند تمامِ السدّ: هذا السدُّ رحمةٌ من ربّي بعباده، فإذا جاء وعدُ ربّي بقربِ الساعةِ جعله مستويًا بالأرضِ مدكوكًا، وكان وعدُ ربّي حقًّا لا خُلفَ فيه؛ ففي هذا ردُّ النعمةِ إلى الله عند تمامها، والتذكيرُ بزوالِ كلِّ شيءٍ عند وعدِ الله؛ فإذا تمّ لك عملٌ فاردده لفضلِ الله، واعلم أنّ كلَّ حائلٍ يزول عند أمرِ الله، ووعدُه آتٍ حقًّا.","source":"تفسير السعدي","grade":"ma'thur"},"names":["هذا رحمة من ربي","وكان وعد ربي حقا"],"heart_state":{"text":"ردُّ النعمةِ لله عند تمامها، واليقينُ بحقّيّةِ وعده."},"action":{"text":"إذا وُفِّقت لإنجازِ خيرٍ فاردده إلى فضلِ الله ورحمته لا إلى حولك، واستحضر أنّ كلَّ عظيمٍ يزول عند وعدِ الله؛ فوعدُه بالبعثِ والجزاءِ حقٌّ لا شكَّ فيه."}}]},{"title":"مشاهدُ القيامةِ وعرضُ جهنم","range":[99,102],"theme":"موجُ الخلقِ يومَ البعث، وعرضُ جهنمَ للغافلين المعرضين","verses":[{"n":99,"reflection":{"text":"«وتركنا بعضهم يومئذ يموج في بعض ونفخ في الصور فجمعناهم جمعا»، وتركنا الخلقَ يومئذٍ (عند خروجِ يأجوجَ ومأجوجَ أو يومَ القيامة) يختلط بعضهم ببعضٍ من الكثرةِ والهول، ونُفِخ في الصورِ فجمعناهم للحسابِ جمعًا لا يتخلّف منه أحد؛ ففي هذا هولُ الجمعِ العظيمِ يوم القيامة؛ فاستحضر ذلك الجمعَ المهيبَ واستعدَّ له بالعملِ الصالح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ الجمعِ يومَ القيامةِ والاستعدادُ له."},"action":{"text":"استحضر يومَ يُنفَخ في الصورِ فيُجمَع الخلقُ كلُّهم للحساب، يموج بعضهم في بعض؛ وأعِدَّ لذلك الموقفِ زادًا من العملِ الصالحِ والتقوى قبل فواتِ الأوان."}},{"n":100,"reflection":{"text":"«وعرضنا جهنم يومئذ للكافرين عرضا»، وأظهرنا جهنمَ يومئذٍ للكافرين إظهارًا بيّنًا يرونها عِيانًا؛ ففي هذا تحقّقُ الوعيدِ ومعاينةُ الكافرين للنارِ التي أنكروها؛ فاعمل على أن تُصرَف عنك النارُ التي تُعرَض يومئذ، ولا تكن ممّن يعاينها حسرةً.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من النارِ والعملُ على النجاةِ منها."},"action":{"text":"اعمل جاهدًا على أن تنجوَ من النارِ التي تُعرَض يوم القيامةِ للكافرين عِيانًا، بالإيمانِ والطاعةِ والبعدِ عن أسبابِ سخطِ الله؛ فمعاينتُها حسرةٌ لا تُقال."}},{"n":101,"reflection":{"text":"«الذين كانت أعينهم في غطاء عن ذكري وكانوا لا يستطيعون سمعا»: الكافرون الذين كانت أعينهم في غطاءٍ يحجبها عن آياتي وذكري فلا تبصر الحقّ، وكانوا لا يطيقون سماعَ الحقِّ لبغضهم له؛ ففي هذا أنّ الإعراضَ عن ذكرِ الله يُعمي البصيرةَ ويُصِمّ عن الحقّ؛ فافتح قلبك وسمعك لذكرِ الله وآياته، واحذر أن يحجبك الهوى عن الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["عن ذكري"],"heart_state":{"text":"فتحُ القلبِ لذكرِ الله، والحذرُ من حجابِ الغفلة."},"action":{"text":"أقبل بقلبِك وسمعِك وبصرِك على ذكرِ الله وآياته، واحذر أن يغشى قلبك غطاءٌ من الغفلةِ والهوى يحجبك عن الحقّ؛ فذكرُ الله جلاءُ القلبِ ونورُ البصيرة."}},{"n":102,"reflection":{"text":"«أفحسب الذين كفروا أن يتخذوا عبادي من دوني أولياء إنا أعتدنا جهنم للكافرين نزلا»: أفظنّ الكافرون أن ينفعهم اتّخاذُ عبادي (الملائكةِ وعيسى وغيرهم) أولياءَ من دوني يعبدونهم؟ إنا هيّأنا جهنمَ للكافرين منزلًا؛ ففي هذا إبطالُ اتّخاذِ الأولياءِ من دون الله، وأنّ ذلك موجبٌ للنار؛ فلا تتّخذ من دون الله وليًّا تعبده أو ترجوه، وأخلص الولايةَ والعبادةَ لله وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الولايةِ والعبادةِ لله وحده."},"action":{"text":"لا تتّخذ من دون الله وليًّا تعبده أو تصرف له شيئًا من حقّه، مهما علا قدرُه؛ وأخلص عبادتك وولاءك لله وحده، فاتّخاذُ الأندادِ من دونه موجبٌ لسخطه."}}]},{"title":"الأخسرون أعمالًا، وأصحابُ الفردوس","range":[103,106],"theme":"من ضلّ سعيُه وهو يحسب أنه محسن، وحبوطُ عملِ من كفر","verses":[{"n":103,"reflection":{"text":"«قل هل ننبئكم بالأخسرين أعمالا»: قل يا محمد: هل نخبركم بأخسرِ الناسِ أعمالًا وأعظمِهم غبنًا يوم القيامة؟ ففي هذا تشويقٌ للتحذيرِ من أعظمِ الخسران، وأنّ الخسرانَ الحقيقيَّ في العملِ لا في المال؛ فاحرص أن تكون من الرابحين لا الخاسرين، وتفقّد عملك أصحيحٌ مقبول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على أن يكون العملُ رابحًا مقبولًا."},"action":{"text":"تفقّد أعمالك: أصحيحةٌ على السنّةِ خالصةٌ لله أم لا؟ واحرص أشدَّ الحرصِ ألّا تكون من الأخسرين الذين تعبوا ثم خسروا؛ فالعبرةُ بقبولِ العملِ لا بكثرته."}},{"n":104,"reflection":{"text":"«الذين ضل سعيهم في الحياة الدنيا وهم يحسبون أنهم يحسنون صنعا»: هم الذين بطل وضاع سعيهم في الدنيا (لبنائه على غيرِ إيمانٍ ولا اتّباع)، وهم يظنّون أنهم يحسنون العمل؛ ففي هذا أخطرُ أنواعِ الخسران: أن يجتهدَ المرءُ في باطلٍ وهو يحسبه حقًّا؛ فاحرص أن يكون عملك على علمٍ وإخلاصٍ ومتابعة، وتعوّذ بالله أن تحسب باطلك حقًّا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من العملِ الفاسدِ مع ظنِّ الإحسان."},"action":{"text":"احرص أن يقوم عملك على علمٍ صحيحٍ وإخلاصٍ لله ومتابعةٍ للسنّة، وتعوّذ بالله من أن تجتهد في باطلٍ تحسبه حقًّا؛ فراجع دينك على العلمِ لئلا يضيع سعيك."}},{"n":105,"reflection":{"text":"«أولئك الذين كفروا بآيات ربهم ولقائه فحبطت أعمالهم فلا نقيم لهم يوم القيامة وزنا»: أولئك الأخسرون هم الذين كفروا بحججِ ربّهم وأنكروا لقاءه، فبطلت أعمالهم لفقدِ الإيمانِ الذي هو شرطُ قبولها، فلا نجعل لهم يوم القيامةِ قدرًا ولا وزنًا؛ ففي هذا أنّ الإيمانَ شرطُ قبولِ العمل، وأنّ الكفرَ يُحبِط كلَّ عمل؛ فحقّق الإيمانَ بآياتِ الله ولقائه، فبه تُقبَل الأعمالُ ويثقل ميزانك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإيمانِ شرطًا لقبولِ العملِ وثقلِ الميزان."},"action":{"text":"حقّق إيمانك بآياتِ الله وبلقائه ويومِ الحساب، فهو شرطُ قبولِ عملك وثقلِ ميزانك؛ فبلا إيمانٍ يحبط العملُ ولو كثر، ولا يُقام لصاحبه وزن."}},{"n":106,"reflection":{"text":"«ذلك جزاؤهم جهنم بما كفروا واتخذوا آياتي ورسلي هزوا»: ذلك جزاؤهم جهنمُ بسببِ كفرهم واتّخاذهم آياتي ورسلي موضعَ سخريةٍ واستهزاء؛ ففي هذا أنّ الاستهزاءَ بالدينِ ورسلِه من أعظمِ موجباتِ النار؛ فعظّم آياتِ الله ورسلَه، واحذر أشدَّ الحذرِ من الاستهزاءِ بشيءٍ من الدينِ أو أهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله ورسلِه، والحذرُ من الاستهزاءِ بالدين."},"action":{"text":"عظّم آياتِ الله ورسلَه وكلَّ شعائرِ الدين، واحذر أن تستهزئ بشيءٍ منها ولو مازحًا، أو تجالسَ المستهزئين؛ فالاستهزاءُ بالدينِ من موجباتِ جهنم."}}]},{"title":"جزاءُ المؤمنين، وسعةُ كلماتِ الله، وخاتمةُ التوحيد","range":[107,110],"theme":"جناتُ الفردوسِ للمؤمنين، ولا نفادَ لكلماتِ الله، وخلاصةُ الرسالة","verses":[{"n":107,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات كانت لهم جنات الفردوس نزلا»: إنّ الذين جمعوا الإيمانَ والعملَ الصالح كانت لهم جناتُ الفردوسِ (أعلى الجنةِ وأوسطها) منزلًا وضيافةً؛ ففي هذا بشارةُ أهلِ الإيمانِ والعملِ بأعلى المنازل؛ فاجمع بين الإيمانِ والعملِ الصالح، واطلب الفردوسَ الأعلى فهو منتهى الرجاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرغبةُ في الفردوسِ الأعلى بالإيمانِ والعمل."},"action":{"text":"اجمع بين الإيمانِ الصادقِ والعملِ الصالح، واسأل الله الفردوسَ الأعلى فهو أعلى الجنةِ ومنه تُفجَّر أنهارها؛ فاجعل همّتك في العبادةِ متعلّقةً بأرفعِ المنازل."}},{"n":108,"reflection":{"text":"«خالدين فيها لا يبغون عنها حولا»: ماكثين في جناتِ الفردوسِ أبدًا، لا يطلبون عنها تحوّلًا لكمالِ نعيمها ورضاهم بها؛ ففي هذا دوامُ نعيمِ الجنةِ وتمامُ الرضا بها بلا مللٍ ولا انقطاع؛ فاعمل لنعيمٍ لا يزول ولا يُملُّ، واجعل الآخرةَ الباقيةَ أكبرَ همّك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنعيمِ الباقي الذي لا يزول ولا يُملّ."},"action":{"text":"اعمل لدارٍ نعيمها دائمٌ لا يزول ولا يُملّ صاحبه فيطلب سواها؛ واجعل الآخرةَ الباقيةَ أكبرَ همّك وغايةَ سعيك، فالدنيا فانيةٌ والفردوسُ خالد."}},{"n":109,"reflection":{"text":"«قل لو كان البحر مدادا لكلمات ربي لنفد البحر قبل أن تنفد كلمات ربي ولو جئنا بمثله مددا»: قل: لو صار البحرُ حبرًا يُكتَب به كلماتُ ربّي (علمُه وحكمته) لنفد البحرُ قبل أن تنفدَ كلماتُ ربّي، ولو جئنا بمثلِ البحرِ مددًا لنفد أيضًا؛ ففي هذا عظمةُ علمِ الله وكلماتِه التي لا نهايةَ لها؛ فعظّم ربّك الذي لا تنفد كلماته، وتواضع بعلمك أمام علمِه الذي لا يُحاط، ولا تملَّ من طلبِ العلمِ فمعينُه لا ينضب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["كلمات ربي"],"heart_state":{"text":"تعظيمُ علمِ الله اللامتناهي، والتواضعُ أمامه."},"action":{"text":"عظّم ربّك الذي لا تنفد كلماتُه ولا يُحاط بعلمه، وتواضع بعلمك القليلِ أمام علمِه الذي لا حدَّ له؛ ولا تملَّ من التعلّمِ والتدبّر، فبحرُ معاني كلامِه لا ينضب."}},{"n":110,"reflection":{"text":"«قل إنما أنا بشر مثلكم يوحى إلي أنما إلهكم إله واحد فمن كان يرجو لقاء ربه فليعمل عملا صالحا ولا يشرك بعبادة ربه أحدا»: قل يا محمد: إنما أنا بشرٌ مثلكم يوحى إليّ أنّ إلهكم إلهٌ واحد لا شريك له، فمن كان يرجو ثوابَ لقاءِ ربّه فليعمل عملًا صالحًا موافقًا للشرع، ولا يشرك في عبادةِ ربّه أحدًا؛ ففي هذا خلاصةُ الرسالةِ كلِّها: توحيدُ الله، وأنّ العملَ المقبولَ ما جمع الإخلاصَ (لا يشرك) والمتابعةَ (صالحًا)؛ فاجعل عملك خالصًا لله صوابًا على السنّة، فبهما يُقبَل، ورجاءُ لقاءِ الله باعثُ كلِّ عمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إلهكم إله واحد"],"heart_state":{"text":"إخلاصُ العملِ لله ومتابعةُ السنّةِ رجاءَ لقائه."},"action":{"text":"اجعل كلَّ عملٍ خالصًا لله وحده صوابًا على هدي النبيِّ ﷺ، فبهذين الشرطين يُقبَل؛ واستحضر رجاءَ لقاءِ ربّك باعثًا لك على العملِ الصالحِ وتركِ الشرك، فهذه خلاصةُ سورةِ الكهفِ ودعوةِ الرسل."}}]}],"coverage":{"covered":110,"total":110}};
